-- Loot Guide texts in French (frFR).
-- Source language: US English (the keys). Written by the EldoUI authors, game
-- terms as the frFR client uses them. Keep every %s, %d and |c...|r code.
-- Built with the key list of tools/locale/lootguide-template.lua; a missing key
-- shows the English text. Loads only on a frFR client.
