	["A letter from the Scarshield Quartermaster in Blackrock Spire sends you to the orb behind General Drakkisath, which opens Blackwing Lair."] = "Une lettre du Maître de l’intendance Bouclier-balafré au pic Rochenoire vous envoie vers l’orbe derrière le général Drakkisath, qui ouvre le repaire de l’Aile noire.",
