	["A little high for you: a level %d quest."] = "Un peu haut pour vous : une quête de niveau %d.",
	["A little high for you: it starts at level %d."] = "Un peu haut pour vous : commence au niveau %d.",
	["A little low for you: it is %d-%d."] = "Un peu bas pour vous : niveaux %d-%d.",
	["A long break"] = "Une longue pause",
	["a long cooldown kept for hard fights"] = "un long temps de recharge gardé pour les combats difficiles",
	["A milestone to look forward to."] = "Une étape à attendre avec impatience.",
	["A moment in your journal"] = "Un moment dans votre journal",
	["A new goal"] = "Un nouvel objectif",
	["A note"] = "Une note",
	["A note remembers where and when you wrote it, and it can remind you later."] = "Une note se souvient d’où et quand vous l’avez écrite, et peut vous le rappeler plus tard.",
	["A note remembers where and when you wrote it. It can remind you later."] = "Une note se souvient d’où et quand vous l’avez écrite. Elle peut vous le rappeler plus tard.",
	["a one-minute bane; Bane of Agony is used"] = "une malédiction d’une minute ; Malédiction d’agonie est utilisée",
	["A one-time reminder moves to the archive once it has fired or you mark it done."] = "Un rappel unique passe aux archives une fois déclenché ou marqué comme fait.",
	["A page of My Adventure"] = "Une page de Mon aventure",
	["A pin on the world map for each giver of the quests left in the zone the map shows. Hover it for the quests, click it for a waypoint. The map's EldoUI pin switch hides it with the other pins."] = "Un repère sur la carte du monde pour chaque donneur des quêtes qui restent dans la zone affichée. Survolez-le pour les quêtes, cliquez pour un point de passage. Le bouton de repères EldoUI de la carte le masque avec les autres repères.",
	["A pin where the next step of each attunement you are on starts. Click it for the arrow."] = "Une épingle là où commence l’étape suivante de chacun de vos accès. Cliquez dessus pour la flèche.",
	["A place in your journal"] = "Un lieu dans votre journal",
	["a place to find"] = "un lieu à trouver",
	["a profession you do not have"] = "un métier que vous n’avez pas",
	["a quest"] = "une quête",
	["A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "Une quête compte dès que vous l’avez tous les deux et qu’un de ses objectifs avance pendant que vous êtes groupés.",
	["A quest of this event."] = "Une quête de cet événement.",
	["A quest outside dungeons, or a creature and what it drops."] = "Une quête hors des donjons, ou une créature et ce qu’elle laisse tomber.",
	["A quest that needs this standing."] = "Une quête qui demande cette réputation.",
	["A quest that rewards the recipe."] = "Une quête qui donne la recette en récompense.",
	["a racial spell; not modeled"] = "un sort racial ; non modélisé",
	["a raid"] = "un raid",
	["A reached goal moves to the archive instead of staying in the Reached list."] = "Un objectif atteint passe aux archives au lieu de rester dans la liste Atteints.",
	["A reminder"] = "Un rappel",
	["A sample step"] = "Une étape d’exemple",
	["A scroll above the name."] = "Un parchemin au-dessus du nom.",
	["A scroll in a bronze frame above the name, to match the WoW Forever art style."] = "Un parchemin dans un cadre de bronze au-dessus du nom, assorti au style artistique de WoW Forever.",
	["A scroll, the quest giver's exclamation mark, a dot in your accent color, a scroll in a bronze frame, or a yellow square with a mark that reads for every kind of color blindness."] = "Un parchemin, le point d’exclamation du donneur de quête, un point de votre couleur d’accent, un parchemin dans un cadre de bronze ou un carré jaune avec une marque lisible pour tout type de daltonisme.",
	["A short card when you enter a zone or a dungeon: your quests there, rares, your notes and your last run. Off in combat."] = "Une petite carte quand vous entrez dans une zone ou un donjon : vos quêtes là-bas, les rares, vos notes et votre dernière sortie. Désactivée en combat.",
	["A short summary of the session during the logout countdown, also kept as a row in the Day view."] = "Un court résumé de la session pendant le compte à rebours de déconnexion, aussi gardé comme une ligne dans la vue Jour.",
	["A short tour of My Adventure."] = "Une courte visite de Mon aventure.",
	["A small dot in your accent color left of the bar."] = "Un petit point de votre couleur d’accent à gauche de la barre.",
	["A small icon on the nameplate of a creature that can drop a quest starter. Needs EldoUI's Nameplates module."] = "Une petite icône sur la barre d’info d’une créature qui peut laisser tomber un objet qui lance une quête. Nécessite le module Nameplates d’EldoUI.",
	["A small mark after each sentence; hover it to see the facts the sentence comes from."] = "Une petite marque après chaque phrase ; survolez-la pour voir les faits d’où vient la phrase.",
	["A solid dark page with no ornaments, numbers first."] = "Une page sombre et unie sans ornements, les chiffres d’abord.",
	["a spell"] = "un sort",
	["A step of %s is here: %s."] = "Une étape de %s est ici : %s.",
	["A step of %s is inside: %s."] = "Une étape de %s est à l’intérieur : %s.",
	["A string with this character's Best in Slot, plan sets, spec and talents (no name or realm) to share."] = "Un texte avec le Best in Slot, les ensembles de plan, la spécialisation et les talents de ce personnage (sans nom ni royaume) à partager.",
	["A strip over the chapters with a mark for each level and its big moments. Click a level to open its chapter. Shown in the level view while no search or filter is on."] = "Une bande au-dessus des chapitres avec une marque pour chaque niveau et ses grands moments. Cliquez sur un niveau pour ouvrir son chapitre. Visible dans la vue par niveau tant qu’aucune recherche ni filtre n’est actif.",
	["A to-do you check off yourself."] = "Une tâche que vous cochez vous-même.",
	["A toast or banner, a sound and a chat line when a wished item is in a loot window or a roll, or drops in the dungeon you enter. Set them in /eui > Loot Guide."] = "Une notification ou une bannière, un son et une ligne de discussion quand un objet souhaité est dans une fenêtre de butin ou un jet, ou tombe dans le donjon où vous entrez. Réglez-les dans /eui > Loot Guide.",
	["A toast when you finish a step or a whole attunement. Nothing is posted to chat."] = "Une notification quand vous terminez une étape ou un accès entier. Rien n’est publié dans la discussion.",
	["A trainer who teaches this recipe."] = "Un maître qui enseigne cette recette.",
	["A vendor during this event."] = "Un marchand pendant cet événement.",
	["A vendor for these rewards."] = "Un marchand pour ces récompenses.",
	["A vendor who sells the recipe."] = "Un marchand qui vend la recette.",
	["A yellow square with a mark above the name; the shape carries it too."] = "Un carré jaune avec une marque au-dessus du nom ; la forme porte aussi l’information.",
	["A zone, or a spot inside one like Frostmane Hold."] = "Une zone, ou un endroit à l’intérieur comme le fort des Givrecrins.",
	["Abandoned"] = "Abandonnée",
	["Abandoned quests"] = "Quêtes abandonnées",
	["Abandoned, failed, or removed by the game. The journal only lists them; nothing is picked up again for you."] = "Abandonnées, échouées ou retirées par le jeu. Le journal ne fait que les lister ; rien n’est repris pour vous.",
	["About %s of play at your recent pace. It counts your own last levels only."] = "Environ %s de jeu à votre rythme récent. Ne compte que vos propres derniers niveaux.",
	["About %s per kill."] = "Environ %s par victoire.",
	["About as good as what you wear"] = "À peu près aussi bon que ce que vous portez",
	["About the same"] = "À peu près pareil",
	["About this zone"] = "À propos de cette zone",
