	["Added %d PvP items from your wishlist to the planner."] = "%d objets JcJ de votre liste de souhaits ajoutés au planificateur.",
	["Added %s to %s."] = "%s ajouté à %s.",
	["Adds a button to the toast that posts one line in guild chat when you click it."] = "Ajoute à la notification un bouton qui publie une ligne dans la discussion de guilde quand vous cliquez dessus.",
	["Adds a Need, Greed or Pass word to that box. It is a label only and never rolls for you."] = "Ajoute un mot Besoin, Cupidité ou Passer à cette case. Ce n’est qu’une étiquette et elle ne lance jamais les dés pour vous.",
	["Adds a Quests line (done of total) to Zone Info's world map tooltip when you hover a zone. Needs the Zone Info module."] = "Ajoute une ligne Quêtes (terminées sur total) à l’infobulle de la carte du monde de Zone Info quand vous survolez une zone. Nécessite le module Zone Info.",
	["Adds it to your goals, so the tracker and the Goals page follow it."] = "L’ajoute à vos objectifs, pour que le suivi et la page Objectifs le suivent.",
	["Adds the best-in-slot items for your spec that you do not own and have not wished for yet."] = "Ajoute les objets Best in Slot de votre spécialisation que vous ne possédez pas et n’avez pas encore souhaités.",
	["Adds the item to your active wishlist, or takes it off every list on show."] = "Ajoute l’objet à votre liste de souhaits active, ou le retire de toutes les listes affichées.",
