	["Dungeons in reach: %s."] = { one = "Donjon à portée : %s.", other = "Donjons à portée : %s." },
	["Dungeons that fit your level, with their quests to take along."] = "Donjons adaptés à votre niveau, avec les quêtes à emporter.",
	["Dungeons together"] = "Donjons ensemble",
	["Dungeons within this many levels of yours count as right for you now (tiles, the level bar and My level only)."] = "Les donjons à ce nombre de niveaux du vôtre comptent comme adaptés maintenant (tuiles, barre de niveau et Mon niveau uniquement).",
	["Dungeons, bosses, quests, zones, mobs and items."] = "Donjons, boss, quêtes, zones, monstres et objets.",
	["Dungeons, bosses, quests, zones, mobs and items. Results show as you type; Enter opens them all."] = "Donjons, boss, quêtes, zones, monstres et objets. Les résultats s’affichent pendant la saisie ; Entrée les ouvre tous.",
	["Each quest you hand in is written here, with where and when."] = "Chaque quête rendue est notée ici, avec le lieu et le moment.",
	["Each run you make here is written down with its time, bosses, and company."] = "Chaque sortie ici est notée avec sa durée, ses boss et ses compagnons.",
