	["EldoUI already knew %d moments of yours from its other records: they are on your Journey."] = { one = "EldoUI connaissait déjà %d de vos moments grâce à ses autres archives : il est dans votre Voyage.", other = "EldoUI connaissait déjà %d de vos moments grâce à ses autres archives : ils sont dans votre Voyage." },
	["EldoUI_LootData"] = "EldoUI_LootData",
