	["EldoUI_LootData is not installed"] = "EldoUI_LootData n’est pas installé",
	["EldoUI_LootData is switched off in the addon list"] = "EldoUI_LootData est désactivé dans la liste des addons",
	["EldoUI_LootData is switched off in the addon list. Turn it on to see quest chains."] = "EldoUI_LootData est désactivé dans la liste des addons. Activez-le pour voir les suites de quêtes.",
	["EldoUI_LootData is too new or too old for this EldoUI"] = "EldoUI_LootData est trop récent ou trop ancien pour cet EldoUI",
	["EldoUI_LootData loads a few seconds after login"] = "EldoUI_LootData se charge quelques secondes après la connexion",
	["EldoUI_LootSim could not load. Check that it is in Interface\\AddOns next to EldoUI."] = "EldoUI_LootSim n’a pas pu être chargé. Vérifiez qu’il est dans Interface\\AddOns à côté d’EldoUI.",
