	["Ends the tour. Start it again with /eui tour journal."] = "Termine la visite. Relancez-la avec /eui tour journal.",
	["Ends the tour. Start it again with Start tour on the Loot Guide settings page or /eui tour lootguide."] = "Termine la visite. Relancez-la avec Lancer la visite sur la page des paramètres du Loot Guide ou /eui tour lootguide.",
	["Engineering"] = "Ingénierie",
	["Enter from level"] = "Entrée dès le niveau",
	["enter from level %d"] = "entrée dès le niveau %d",
	["Enter saves, Shift+Enter new line, Esc closes."] = "Entrée enregistre, Maj+Entrée nouvelle ligne, Échap ferme.",
	["Enter saves, Shift+Enter starts a new line."] = "Entrée enregistre, Maj+Entrée commence une nouvelle ligne.",
