	["Epic finds and the wishlist items you got."] = "Trouvailles épiques et objets de la liste de souhaits obtenus.",
	["Epic finds come from bosses deep in dungeons, later in your journey."] = "Les trouvailles épiques viennent des boss au fond des donjons, plus tard dans votre voyage.",
	["Epic finds come from bosses. These dungeons fit your level:"] = "Les trouvailles épiques viennent des boss. Ces donjons conviennent à votre niveau :",
	["Equip a ranged weapon first."] = "Équipez d’abord une arme à distance.",
	["Equipped %s"] = "%s équipé",
	["Eras"] = "Ères",
	["Esc closes the window too."] = "Échap ferme aussi la fenêtre.",
	["Essentials"] = "L’essentiel",
	["estimate"] = "estimation",
	["Estimates from fights against a target dummy with your own character sheet and public Classic combat rules. Set bonuses and item procs are not counted."] = "Estimations tirées de combats contre une cible d’entraînement avec votre propre fiche de personnage et les règles de combat Classic publiques. Les bonus d’ensemble et les effets d’objets ne sont pas comptés.",
	["Everlook"] = "Long-guet",
	["Every attunement and key step by step. Its next steps show up in Next trips and on Today."] = "Chaque accès et chaque clé étape par étape. Les étapes suivantes apparaissent dans Prochains trajets et sur Aujourd’hui.",
	["Every attunement and key, step by step."] = "Chaque accès et chaque clé, étape par étape.",
	["Every best-in-slot item is already yours or on your wishlist."] = "Chaque objet Best in Slot est déjà à vous ou dans votre liste de souhaits.",
	["Every craft per profession: what it makes, the skill it needs, the reagents you own and where the recipe comes from."] = "Chaque fabrication par métier : ce qu’elle produit, la compétence requise, les composants que vous avez et d’où vient la recette.",
	["Every dungeon and raid with its bosses, loot, drop chances and quests. Inside a dungeon the window opens on it."] = "Chaque donjon et raid avec ses boss, son butin, ses chances et ses quêtes. Dans un donjon, la fenêtre s’ouvre dessus.",
	["Every dungeon and raid: bosses, drops with chances, quests and what is an upgrade for you."] = "Chaque donjon et raid : boss, butins avec chances, quêtes et ce qui est une amélioration pour vous.",
	["Every flight master you speak to adds a flight path. These zones fit your level:"] = "Chaque maître de vol à qui vous parlez ajoute un trajet. Ces zones conviennent à votre niveau :",
	["Every idea for where to go next, with filters."] = "Toutes les idées de prochaine destination, avec des filtres.",
	["Every idea, best first, with filters for dungeons, quests, attunements, and zones, for your group and the time you have. Hover a card to see every reason; Not now puts it away until your next level."] = "Toutes les idées, la meilleure d’abord, avec des filtres pour les donjons, quêtes, accès et zones, pour votre groupe et le temps dont vous disposez. Survolez une fiche pour voir chaque raison ; Pas maintenant la range jusqu’à votre prochain niveau.",
	["Every item, creature, quest and place in sortable tables with filters and a detail panel."] = "Chaque objet, créature, quête et lieu dans des tableaux triables avec filtres et panneau de détails.",
	["Every item, mob, quest and vendor the loot data knows, with filters and sorting."] = "Chaque objet, monstre, quête et marchand connus des données de butin, avec filtres et tri.",
	["Every keepsake, grouped by kind."] = "Tous les souvenirs, groupés par type.",
	["Every kind of result."] = "Tous les types de résultats.",
	["Every level is behind you"] = "Tous les niveaux sont derrière vous",
	["Every level is behind you. The journal keeps writing down your runs, finds, and standings."] = "Tous les niveaux sont derrière vous. Le journal continue de noter vos sorties, trouvailles et réputations.",
	["Every login"] = "À chaque connexion",
	["Every Loot Guide page is switched off. Turn pages on in /eui > Loot Guide."] = "Toutes les pages du Loot Guide sont désactivées. Activez des pages dans /eui > Loot Guide.",
	["Every moment."] = "Chaque moment.",
	["Every new standing"] = "Chaque nouvelle réputation",
	["Every new standing, or Honored and up only. Changing it on a preset turns it into Custom."] = "Chaque nouvelle réputation, ou seulement Honoré et plus. La modifier sur un préréglage le transforme en Personnalisé.",
	["Every part and chapter of the Book. Click one to turn to it."] = "Chaque partie et chapitre du Livre. Cliquez dessus pour y aller.",
	["Every PvP reward with its cost and the rank or standing it needs, plus a planner for the weeks to afford them."] = "Chaque récompense JcJ avec son coût et le rang ou la réputation requis, plus un planificateur des semaines pour les payer.",
	["Every quest you handed in since the journal began, with where, when, and what it gave."] = "Chaque quête rendue depuis le début du journal, avec le lieu, le moment et ce qu’elle a rapporté.",
	["Every quest you handed in, with where, when, who gave it, and who came along; your quest log; and the quests the game remembers from before."] = "Chaque quête rendue, avec le lieu, le moment, qui l’a donnée et qui vous accompagnait ; votre journal de quêtes ; et les quêtes dont le jeu se souvient d’avant.",
	["Every run the Instances module recorded."] = "Chaque sortie enregistrée par le module Instances.",
	["Every step for both sides and every class, also content the client does not list yet."] = "Chaque étape pour les deux camps et chaque classe, y compris le contenu que le client ne liste pas encore.",
	["Every suggestion, best first."] = "Chaque suggestion, la meilleure d’abord.",
	["Every time"] = "À chaque fois",
	["Every way to get one item."] = "Toutes les façons d’obtenir un objet.",
	["Every zone"] = "Chaque zone",
	["Every zone you visited, with its corners, time, kills, and quests, and every dungeon with its runs."] = "Chaque zone visitée, avec ses recoins, son temps, ses victoires et ses quêtes, et chaque donjon avec ses sorties.",
	["Every zone's quests: how many you have done, what is left and who gives it, with a Map button for each giver."] = "Les quêtes de chaque zone : combien vous en avez terminé, ce qui reste et qui les donne, avec un bouton Carte pour chaque donneur.",
	["Everyone"] = "Tout le monde",
	["Everyone falls sometime. There is no need to chase this one."] = "Tout le monde tombe un jour. Inutile de courir après celui-ci.",
	["Everyone falls sometime. There is no need to chase this one; here is what fits you instead:"] = "Tout le monde tombe un jour. Inutile de courir après celui-ci ; voici ce qui vous convient à la place :",
	["Everyone you grouped with."] = "Tous ceux avec qui vous avez été groupé.",
	["Everything"] = "Tout",
	["Everything is selected. Press Ctrl+C and share it. It holds your gear plans, spec and talents, not your name or realm."] = "Tout est sélectionné. Appuyez sur Ctrl+C et partagez-le. Il contient vos plans d’équipement, spécialisation et talents, pas votre nom ni votre royaume.",
	["Everything is selected. Press Ctrl+C and share it. Others paste it into /eui import or the wishlist's Import."] = "Tout est sélectionné. Appuyez sur Ctrl+C et partagez-le. Les autres le collent dans /eui import ou dans l’Import de la liste de souhaits.",
	["Everything reached. Start a new one with New goal."] = "Tout est atteint. Commencez-en un nouveau avec Nouvel objectif.",
	["Everything you can get at your level is already as good as what you wear."] = "Tout ce que vous pouvez obtenir à votre niveau vaut déjà ce que vous portez.",
	["Everything, rare (blue) finds too, long chapters, every chapter open and a taller tracker."] = "Tout, y compris les trouvailles rares (bleues), de longs chapitres, chaque chapitre ouvert et un suivi plus haut.",
	["Exalted"] = "Exalté",
	["Excavation Site"] = "Site de fouilles",
	["Exclamation mark"] = "Point d’exclamation",
	["Experience"] = "Expérience",
	["Experience and money next to each quest you handed in."] = "Expérience et argent à côté de chaque quête rendue.",
	["Explored %s"] = "%s exploré",
	["Export"] = "Exporter",
	["Export (share string)"] = "Exporter (texte à partager)",
	["Export a printable page"] = "Exporter une page imprimable",
	["Export as Markdown"] = "Exporter en Markdown",
