	["Export formats: %s."] = "Formats d’export : %s.",
	["Faction"] = "Faction",
	["Faction %d"] = "Faction %d",
	["Factions that count you as Honored or better."] = "Factions qui vous considèrent comme Honoré ou mieux.",
	["falls"] = "chutes",
	["Fanfare's \"Journal moment\" triggers play or show with each moment. While such a trigger, or a level-up or boss-kill trigger, has a sound, the moment plays none of its own, so you hear one sound."] = "Les déclencheurs \"Moment du journal\" de Fanfare jouent ou affichent quelque chose avec chaque moment. Tant qu'un tel déclencheur, ou un déclencheur de montée de niveau ou de boss vaincu, a un son, le moment ne joue pas le sien, pour que vous n'entendiez qu'un son.",
	["Farmed for %s"] = "Farmé pendant %s",
	["Fast (8 ms a frame)"] = "Rapide (8 ms par image)",
	["fastest"] = "le plus rapide",
	["Feet"] = "Pieds",
	["Fellowship"] = "Communauté",
	["Fewer"] = "Moins",
	["Fiery Weapon"] = "Arme flamboyante",
	["Lifestealing"] = "Vol de vie",
	["Fight"] = "Combat",
	["Fighting"] = "En combat",
	["Fights against a target dummy with the best items of your list (one-minute fights, out of combat). Progress shows here, in the datatext and as a toast when done."] = "Combats contre une cible d’entraînement avec les meilleurs objets de votre liste (combats d’une minute, hors combat). La progression s’affiche ici, dans le texte d’info et en notification à la fin.",
	["Fights against a target dummy with the best items of your list per slot: a quick pass, exact runs of the top picks, then the best set (one-minute fights, out of combat)."] = "Combats contre une cible d’entraînement avec les meilleurs objets de votre liste par emplacement : un passage rapide, des simulations exactes des meilleurs choix, puis le meilleur ensemble (combats d’une minute, hors combat).",
	["Fights against a target dummy with this item instead of what you wear in its slot (about a second, out of combat). The result shows here, in the tooltip and as a toast."] = "Combats contre une cible d’entraînement avec cet objet au lieu de celui que vous portez à cet emplacement (environ une seconde, hors combat). Le résultat s’affiche ici, dans l’infobulle et en notification.",
	["Fights against a target dummy with your own character sheet. Slower, but counts how your talents and spells use each stat. Items not simulated yet keep the weights gain."] = "Combats contre une cible d’entraînement avec votre propre fiche de personnage. Plus lent, mais compte comment vos talents et sorts utilisent chaque caractéristique. Les objets pas encore simulés gardent le gain pondéré.",
	["Fights against a target dummy with your own character sheet: DPS numbers for your gear, Best in Slot and plan sets. /eui sim opens its window."] = "Combats contre une cible d’entraînement avec votre propre fiche de personnage : chiffres de DPS pour votre équipement, Best in Slot et ensembles de plan. /eui sim ouvre sa fenêtre.",
	["Fills an empty slot"] = "Remplit un emplacement vide",
	["Fills the set with the Best in Slot items (the simulated set in Simulator mode)."] = "Remplit l’ensemble avec les objets Best in Slot (l’ensemble simulé en mode Simulateur).",
	["Fills the set with your equipped gear."] = "Remplit l’ensemble avec votre équipement porté.",
