	["Filter: pick your spec, the armor you wear and where your gear may come from. Every page and tooltip uses the same list."] = "Filtre : choisissez votre spécialisation, l’armure que vous portez et d’où peut venir votre équipement. Chaque page et infobulle utilise la même liste.",
