	["notes and more"] = "notes et plus",
	["Notes on the world map"] = "Notes sur la carte du monde",
	["Notes remember where and when you wrote them. Press Enter in the box above to save one."] = "Les notes retiennent où et quand vous les avez écrites. Appuyez sur Entrée dans le champ ci-dessus pour en enregistrer une.",
	["Notes show as pins on the world map and minimap where you wrote them, with the Map Notes switch. Needs the Map Notes module."] = "Les notes s'affichent comme repères sur la carte du monde et la minicarte là où vous les avez écrites, avec l'interrupteur Notes de carte. Nécessite le module Notes de carte.",
	["Notes that remember where and when you wrote them, and reminders that show when you get somewhere."] = "Des notes qui retiennent où et quand vous les avez écrites, et des rappels qui s'affichent quand vous arrivez quelque part.",
	["Notes the quests, dungeons and zone level ranges the game shows you that the quest data does not know yet, so the quest pages can show them. Only what dialogs and the map show is read."] = "Note les quêtes, donjons et tranches de niveau des zones que le jeu vous montre et que les données de quêtes ne connaissent pas encore, pour que les pages de quêtes puissent les afficher. Seul ce que montrent les dialogues et la carte est lu.",
	["Notes written here"] = "Notes écrites ici",
