	["Notes you archived. Restore or delete them there."] = "Les notes que vous avez archivées. Restaurez-les ou supprimez-les là.",
	["Nothing changed: %s"] = "Rien n'a changé : %s",
	["Nothing fits: turn on Higher levels, or install EldoUI_LootData for the full item list."] = "Rien ne convient : activez Niveaux supérieurs, ou installez EldoUI_LootData pour la liste complète des objets.",
	["Nothing fits: widen the filter or turn on Higher levels."] = "Rien ne convient : élargissez le filtre ou activez Niveaux supérieurs.",
	["Nothing found"] = "Rien trouvé",
	["Nothing here fits your level."] = "Rien ici ne convient à votre niveau.",
