	["Nothing in this group."] = "Rien dans ce groupe.",
	["Nothing is lost: it merges with what My Adventure has, a backup is taken first, and Undo puts it back. Forever Journal's own data is only read, never changed."] = "Rien n'est perdu : c'est fusionné avec ce que Mon aventure contient, une sauvegarde est faite d'abord, et Annuler remet tout en place. Les données propres de Forever Journal sont seulement lues, jamais modifiées.",
