	["Nothing new to report yet. The Journal notes the quests, dungeons, and zones the data does not know as you meet them."] = "Rien de nouveau à signaler pour l'instant. Le Journal note les quêtes, donjons et zones que les données ne connaissent pas, à mesure que vous les rencontrez.",
