	["Numbered boss markers from the loot data on the dungeon map window. They never show where you are."] = "Marqueurs de boss numérotés, tirés des données de butin, dans la fenêtre de carte du donjon. Ils ne montrent jamais où vous êtes.",
	["Numbered markers are the bosses, from the Classic data. Click one for its loot; click it again to close the list."] = "Les marqueurs numérotés sont les boss, d'après les données Classic. Cliquez sur l'un d'eux pour son butin ; cliquez à nouveau pour fermer la liste.",
	["Object"] = "Objet",
