	["OK"] = "OK",
	["on (Mob and Loot Info)"] = "activé (Infos créatures et butin)",
	["On a character that gives, takes or is the target of an attunement step: which step and how far you are. Nothing shows when the game hides who it is."] = "Sur un personnage qui donne, reçoit ou est la cible d'une étape d'accès : quelle étape et où vous en êtes. Rien ne s'affiche quand le jeu cache de qui il s'agit.",
	["On a level-up the moment links to the dungeons, quests, spells and attunement steps that just opened."] = "Lors d'une montée de niveau, le moment renvoie vers les donjons, quêtes, sorts et étapes d'accès qui viennent de s'ouvrir.",
	["On a quest link: when you took it or handed it in, at what level and where, and whether it is part of your next trip."] = "Sur un lien de quête : quand vous l'avez prise ou rendue, à quel niveau et où, et si elle fait partie de votre prochain trajet.",
	["On an item that is a step of an attunement: which one, whether you have it, and with Shift the next step."] = "Sur un objet qui est une étape d'accès : lequel, si vous l'avez et, avec Maj, l'étape suivante.",
	["On an item:"] = "Sur un objet :",
	["On an item: when and where your journal saw you find it or put it on, and at what level."] = "Sur un objet : quand et où votre journal vous a vu le trouver ou l'équiper, et à quel niveau.",
