	["Opens a card that compares the item with what you wear, its source and your plans."] = "Ouvre une carte qui compare l'objet à ce que vous portez, avec sa source et vos plans.",
	["Opens a copy box with the Forever quests you took, to send to EldoUI's authors so the dungeon can get a full chain."] = "Ouvre une zone de copie avec les quêtes de Forever que vous avez prises, à envoyer aux auteurs d'EldoUI pour que le donjon reçoive une chaîne complète.",
	["Opens a copy box with the list, to send to EldoUI's authors so the dungeon can get a full chain."] = "Ouvre une zone de copie avec la liste, à envoyer aux auteurs d'EldoUI pour que le donjon reçoive une chaîne complète.",
	["Opens EldoUI's keybind mode. My Adventure's keys (open or close it, quick note, the tracker, and Next trips) are also under Options > Keybindings > AddOns > EldoUI."] = "Ouvre le mode raccourcis d'EldoUI. Les touches de Mon aventure (l'ouvrir ou le fermer, note rapide, le suivi et Prochains trajets) se trouvent aussi dans Options > Raccourcis > AddOns > EldoUI.",
