	["Opens the Dungeons tab: every dungeon and raid with its bosses, loot and quests."] = "Ouvre l'onglet Donjons : chaque donjon et raid avec ses boss, son butin et ses quêtes.",
	["Opens the game's group finder window. Nothing is listed or queued for you."] = "Ouvre la fenêtre de recherche de groupe du jeu. Rien n'est inscrit ni mis en file d'attente pour vous.",
