	["Outdated: your gear, talents, level or the fight settings changed since this run. Press Sim to run it again."] = "Obsolète : votre équipement, vos talents, votre niveau ou les réglages de combat ont changé depuis ce calcul. Appuyez sur Sim pour le relancer.",
