	["Pass"] = "Passer",
	["Paste a journal backup code starting with !EUJ1!, FJ2: or FJ1:. You see what it holds before anything changes."] = "Collez un code de sauvegarde de journal commençant par !EUJ1!, FJ2: ou FJ1:. Vous voyez son contenu avant toute modification.",
	["Paste a journal code"] = "Coller un code de journal",
	["Paste a wishlist string (Ctrl+V) and click Save."] = "Collez un texte de liste de souhaits (Ctrl+V) et cliquez sur Enregistrer.",
	["Paste it into a journal-data issue. It changes nothing in your game."] = "Collez-le dans un ticket journal-data. Cela ne change rien dans votre jeu.",
	["paused for combat"] = "en pause pendant le combat",
	["Paused for combat. The run goes on when combat ends."] = "En pause pendant le combat. Le calcul reprend à la fin du combat.",
	["People"] = "Personnes",
	["People you grouped with long enough for the journal to remember."] = "Les personnes avec qui vous avez été groupé assez longtemps pour que le journal s'en souvienne.",
	["People you grouped with long enough for the journal to remember. Names show while Name companions is on."] = "Les personnes avec qui vous avez été groupé assez longtemps pour que le journal s'en souvienne. Les noms s'affichent tant que Nommer les compagnons est activé.",
	["Pet"] = "Familier",
	["pet cooldowns are not modeled"] = "les temps de recharge des familiers ne sont pas modélisés",
	["Pick a backup, then Merge (keeps everything since) or Replace (exactly as it was). Your journal is backed up first."] = "Choisissez une sauvegarde, puis Fusionner (garde tout ce qui a suivi) ou Remplacer (exactement comme c'était). Votre journal est sauvegardé d'abord.",
	["Pick a craft to see its reagents and where the recipe comes from."] = "Choisissez une recette pour voir ses composants et d'où vient la recette.",
	["Pick a craft: its reagents with what you own and where the recipe comes from, with Map buttons."] = "Choisissez une recette : ses composants avec ce que vous possédez et d'où vient la recette, avec des boutons Carte.",
	["Pick a faction on the left."] = "Choisissez une faction à gauche.",
	["Pick a level above the one you have."] = "Choisissez un niveau au-dessus du vôtre.",
	["Pick a quest on the left to see its chain, objectives and rewards."] = "Choisissez une quête à gauche pour voir sa chaîne, ses objectifs et ses récompenses.",
	["Pick a row to see it here."] = "Choisissez une ligne pour la voir ici.",
	["Pick a zone"] = "Choisir une zone",
	["Pick an attunement from the list, or type its name."] = "Choisissez un accès dans la liste, ou tapez son nom.",
	["Pick an item from your wishlist."] = "Choisissez un objet de votre liste de souhaits.",
	["pick one and open it in the Loot Guide"] = "en choisir un et l’ouvrir dans le Loot Guide",
	["Pick the list the stars add to, show other lists, make, rename, share or delete lists."] = "Choisissez la liste à laquelle les étoiles ajoutent, affichez d'autres listes, créez, renommez, partagez ou supprimez des listes.",
	["Pick the target dummy's level and the fight length. Bosses are three levels above you."] = "Choisissez le niveau du mannequin d'entraînement et la durée du combat. Les boss ont trois niveaux de plus que vous.",
	["Pick up a quest and it shows here until you hand it in."] = "Prenez une quête et elle s'affichera ici jusqu'à ce que vous la rendiez.",
	["Pick up its quests before you go."] = "Prenez ses quêtes avant de partir.",
	["Pick up: %s"] = "À prendre : %s",
	["Pick what you want to work towards."] = "Choisissez ce vers quoi vous voulez avancer.",
	["Picked up %s · %s ago"] = "Prise le %s · il y a %s",
	["Picked up %s · handed in %s · took %s"] = "Prise le %s · rendue le %s · durée %s",
	["Picked up in %s"] = "Prise à %s",
	["Picks new wording for the whole Book. The facts don't change."] = "Choisit une nouvelle formulation pour tout le Livre. Les faits ne changent pas.",
	["Picks new wording for the whole story. The facts don't change."] = "Choisit une nouvelle formulation pour toute l'histoire. Les faits ne changent pas.",
	["Pin"] = "Épingler",
