	["Pinned"] = "Épinglé",
	["pinned"] = "épinglé",
	["Pinned notes"] = "Notes épinglées",
	["Pins at dungeon and raid entrances on the world and zone maps, with the level range and your upgrades inside. Where the game draws its own entrance pin, ours steps aside, so no entrance shows twice."] = "Repères aux entrées des donjons et raids sur les cartes du monde et des zones, avec la tranche de niveau et vos améliorations à l'intérieur. Là où le jeu affiche son propre repère d'entrée, le nôtre s'efface, pour qu'aucune entrée n'apparaisse en double.",
	["Pins for the givers of quests you can pick up now."] = "Des repères pour les donneurs des quêtes que vous pouvez prendre maintenant.",
	["Pins the biggest of %d camps on your map. Click again for the next one; after the last the pin goes away."] = { one = "Place un repère sur le plus grand des %d camps sur votre carte. Cliquez à nouveau pour le suivant ; après le dernier, le repère disparaît.", other = "Place un repère sur le plus grand des %d camps sur votre carte. Cliquez à nouveau pour le suivant ; après le dernier, le repère disparaît." },
	["Pins the dungeon's entrance on your map."] = "Place un repère sur l'entrée du donjon sur votre carte.",
	["Pins the entrance in %s on your map and turns on the arrow."] = "Place un repère sur l'entrée à %s sur votre carte et active la flèche.",
	["Pins the entrance on your map and opens the map there (out of combat)."] = "Place un repère sur l'entrée sur votre carte et y ouvre la carte (hors combat).",
	["Pins the entrance on your map."] = "Place un repère sur l'entrée sur votre carte.",
	["Pins the instance entrance on your map and turns on the arrow."] = "Place un repère sur l'entrée de l'instance sur votre carte et active la flèche.",
	["Pins the instance entrance on your map, turns on the arrow and opens the map there (out of combat)."] = "Place un repère sur l'entrée de l'instance sur votre carte, active la flèche et y ouvre la carte (hors combat).",
	["Pins the place on your map and turns on the arrow."] = "Place un repère sur le lieu sur votre carte et active la flèche.",
	["Pins the place on your map and turns on the arrow. Click again to take the pin away."] = "Place un repère sur le lieu sur votre carte et active la flèche. Cliquez à nouveau pour retirer le repère.",
	["Place"] = "Lieu",
	["Places"] = "Lieux",
	["Places the boss markers by where the creatures stand in the Classic data, on a plain grid. Approximate: walls and floors are not drawn."] = "Place les marqueurs de boss là où se tiennent les créatures selon les données Classic, sur une grille simple. Approximatif : les murs et les sols ne sont pas dessinés.",
	["Plan"] = "Plan",
	["Plan pieces to see the total and how many weeks of your recent honor each one takes."] = "Planifiez des pièces pour voir le total et combien de semaines de votre honneur récent chacune demande.",
