	["Played for %s"] = "Joué pendant %s",
	["Player notes"] = "Notes de joueurs",
	["Plays moment sounds on the Master channel."] = "Joue les sons des moments sur le canal principal.",
	["Plays with the toast for a finished attunement. Step toasts are silent."] = "Joué avec la notification d'un accès terminé. Les notifications d'étape sont muettes.",
	["Plays with this kind of moment. None: the card stays quiet."] = "Joué avec ce type de moment. Aucun : la carte reste silencieuse.",
	["Poison"] = "Poison",
	["Poor"] = "Médiocre",
	["Poor (gray)"] = "Médiocre (gris)",
	["Posts one line in guild chat."] = "Écrit une ligne dans la discussion de guilde.",
	["Press %s to take a screenshot. Click or press Esc to close."] = "Appuyez sur %s pour faire une capture d'écran. Cliquez ou appuyez sur Échap pour fermer.",
	["Press Ctrl+C to copy it, save it as a .html file and open it in a browser. Print it to PDF for a keepsake."] = "Appuyez sur Ctrl+C pour copier, enregistrez-le dans un fichier .html et ouvrez-le dans un navigateur. Imprimez-le en PDF pour en garder un souvenir.",
	["Press Ctrl+C to copy it, then paste it anywhere."] = "Appuyez sur Ctrl+C pour copier, puis collez-le où vous voulez.",
	["Press Ctrl+C to copy it, then paste it into any Markdown editor or note app."] = "Appuyez sur Ctrl+C pour copier, puis collez-le dans un éditeur Markdown ou une application de notes.",
	["Press Ctrl+C to copy the code. Use \"Paste a journal code\" on this PC or another to restore the journal. Nothing is sent anywhere."] = "Appuyez sur Ctrl+C pour copier le code. Utilisez \"Coller un code de journal\" sur ce PC ou un autre pour restaurer le journal. Rien n'est envoyé nulle part.",
	["Press Ctrl+C to copy. Nothing is sent anywhere: paste it where you like."] = "Appuyez sur Ctrl+C pour copier. Rien n'est envoyé nulle part : collez-le où vous voulez.",
	["Press Ctrl+C to copy. Paste it back in with Paste a journal code, on this PC or another. Nothing is sent anywhere."] = "Appuyez sur Ctrl+C pour copier. Recollez-le avec Coller un code de journal, sur ce PC ou un autre. Rien n'est envoyé nulle part.",
	["Press Sim to compare the checked sets in the same fights."] = "Appuyez sur Sim pour comparer les ensembles cochés dans les mêmes combats.",
	["Press Sim to read your character and fight a target dummy 120 times. It takes a few seconds and runs out of combat."] = "Appuyez sur Sim pour lire votre personnage et combattre un mannequin d'entraînement 120 fois. Cela prend quelques secondes et se fait hors combat.",
	["Previews a code starting with !EUJ1!, FJ2: or FJ1:. A full backup can be merged or used to replace your journal. Recent changes are merged."] = "Affiche un aperçu d'un code commençant par !EUJ1!, FJ2: ou FJ1:. Une sauvegarde complète peut être fusionnée ou remplacer votre journal. Les modifications récentes sont fusionnées.",
	["Previous pages"] = "Pages précédentes",
	["Prints where the loot data comes from (same as /lg data)."] = "Affiche d'où viennent les données de butin (comme /lg data).",
	["Prints where the loot data comes from, its version and size (same as /lg data)."] = "Affiche d'où viennent les données de butin, leur version et leur taille (comme /lg data).",
