	["Puts a group line into the chat box. Nothing is sent until you press Enter."] = "Met une ligne de groupe dans la zone de saisie. Rien n'est envoyé avant que vous appuyiez sur Entrée.",
	["Puts every journal the last import touched back as it was before, and its settings too."] = "Remet chaque journal touché par la dernière importation comme il était avant, avec ses réglages.",
	["Puts every piece you do not have on your active wishlist."] = "Met chaque pièce que vous n'avez pas sur votre liste de souhaits active.",
	["Puts its quests that are already in your log on the objective tracker. Nothing is accepted for you."] = "Met ses quêtes déjà présentes dans votre journal dans le suivi des objectifs. Rien n'est accepté pour vous.",
	["Puts one line about your character in the chat box. You read it and press Enter to send it."] = "Met une ligne sur votre personnage dans la zone de saisie. Vous la relisez et appuyez sur Entrée pour l'envoyer.",
	["Puts the item in this plan set on the Best in Slot page, or takes it out. Plan sets are plans, not equipment sets."] = "Met l'objet dans cet ensemble du plan sur la page Best in Slot, ou l'en retire. Les ensembles du plan sont des plans, pas des ensembles d'équipement.",
