	["Shows on the Attunements tab how many attunements, steps and quests are loaded and the data version."] = "Affiche sur l'onglet Accès combien d'accès, d'étapes et de quêtes sont chargés et la version des données.",
	["Shows only instances within the level window of yours (Loot Guide settings)."] = "N'affiche que les instances dans votre fenêtre de niveau (réglages du Loot Guide).",
	["Shows only items that beat what you wear, rated by the shared item engine."] = "N'affiche que les objets meilleurs que ce que vous portez, évalués par le moteur d'objets commun.",
	["Shows only rares and creatures that drop an upgrade for you."] = "N'affiche que les monstres rares et les créatures qui donnent une amélioration pour vous.",
	["Shows only rewards that beat what you wear."] = "N'affiche que les récompenses meilleures que ce que vous portez.",
	["Shows only this armor kind. Click again for all."] = "N'affiche que ce type d'armure. Cliquez à nouveau pour tout voir.",
	["Shows that attunement."] = "Affiche cet accès.",
	["Shows the attunements before these as columns."] = "Affiche les accès précédents en colonnes.",
	["Shows the item on your character in the dressing room."] = "Affiche l'objet sur votre personnage dans la cabine d'essayage.",
	["Shows the next attunements as columns."] = "Affiche les accès suivants en colonnes.",
	["Shows the note on your Journey, under the level you wrote it at."] = "Affiche la note dans votre Voyage, sous le niveau auquel vous l'avez écrite.",
	["Shows the place's creatures in the Mobs table."] = "Affiche les créatures du lieu dans le tableau Monstres.",
	["Shows the quest in the Quests table."] = "Affiche la quête dans le tableau Quêtes.",
	["Shows the quests for this place in the Quests table."] = "Affiche les quêtes de ce lieu dans le tableau Quêtes.",
	["Shows the three best drops only."] = "N'affiche que les trois meilleurs butins.",
	["Shows the zone's creatures in the Mobs table."] = "Affiche les créatures de la zone dans le tableau Monstres.",
	["Shows this floor. Your pick is remembered for this dungeon."] = "Affiche cet étage. Votre choix est retenu pour ce donjon.",
	["Shows this note on your Journey, under the level you wrote it at."] = "Affiche cette note dans votre Voyage, sous le niveau auquel vous l'avez écrite.",
	["Shows what the tab has loaded, here in the window."] = "Affiche ici, dans la fenêtre, ce que l'onglet a chargé.",
	["Shows what was noted as one block to copy into a journal-data issue. Nothing is sent from the game."] = "Affiche ce qui a été noté en un bloc à copier dans un ticket journal-data. Rien n'est envoyé depuis le jeu.",
