	["Switched off."] = "Désactivé.",
	["Switches the Alts module on. Each character is added the next time you log in on it."] = "Active le module Personnages. Chaque personnage est ajouté la prochaine fois que vous vous connectez avec lui.",
	["Switches the Loot Guide module on; My Adventure comes with it."] = "Active le module Loot Guide ; Mon aventure vient avec.",
	["Switches the Loot Guide module on; quest starter hints come with it."] = "Active le module Loot Guide ; les indices des objets qui lancent une quête viennent avec.",
