	["Take the tour"] = "Faire la visite",
	["Taken"] = "Prise",
	["Taken at %s. You find it in the Screenshots folder of your game."] = "Prise à %s. Vous la trouverez dans le dossier Screenshots de votre jeu.",
	["taken before the journal kept track"] = "prise avant que le journal ne note",
	["Taken before the journal kept track."] = "Prise avant que le journal ne note.",
	["Taken off your keepsakes."] = "Retiré de vos souvenirs.",
	["Takes a backup of this journal now."] = "Fait une sauvegarde de ce journal maintenant.",
	["Takes about %d minutes."] = { one = "Prend environ %d minute.", other = "Prend environ %d minutes." },
	["Takes it off your keepsakes."] = "Le retire de vos souvenirs.",
	["Takes one screenshot of the card, without this button and the hint. It goes to the Screenshots folder of your game."] = "Fait une capture d'écran de la carte, sans ce bouton ni l'indication. Elle va dans le dossier Screenshots de votre jeu.",
	["Takes step %d: %s"] = "Reçoit l'étape %d : %s",
	["Takes this note off your Journey."] = "Retire cette note de votre Voyage.",
	["Taking it with you"] = "L'emporter avec vous",
	["Talents are read by name, which works on English game clients only. On this client the simulator plays without talent effects."] = "Les talents sont lus par leur nom, ce qui ne fonctionne qu'avec les clients de jeu en anglais. Sur ce client, le simulateur joue sans les effets des talents.",
	["Talents the simulator plays"] = "Talents joués par le simulateur",
	["Tank"] = "Tank",
	["Tank: avoidance pick (%s holds more threat)"] = "Tank : choix pour l'évitement (%s génère plus de menace)",
	["Tank: close call with %s"] = "Tank : de peu devant %s",
	["Tank: threat pick (%s holds more avoidance)"] = "Tank : choix pour la menace (%s a plus d'évitement)",
	["Target"] = "Cible",
	["target level %d"] = "cible niveau %d",
	["Teaches"] = "Enseigne",
	["Tell the guild"] = "Le dire à la guilde",
	["Tell the guild button"] = "Bouton Le dire à la guilde",
	["Telling"] = "Envoi",
	["Tells you when a wishlist item is in a loot window or a roll, or drops in the dungeon you enter. It never loots or rolls for you."] = "Vous prévient quand un objet de la liste de souhaits est dans une fenêtre de butin ou un jet, ou tombe dans le donjon où vous entrez. Il ne ramasse ni ne lance les dés pour vous.",
	["Test alert"] = "Alerte de test",
	["Text size of the story in the Book and Story so far, 90 to 140%."] = "Taille du texte du récit dans le Livre et L'histoire jusqu'ici, de 90 à 140 %.",
	["That backup is gone."] = "Cette sauvegarde n'existe plus.",
	["That dungeon is not in the dungeon list."] = "Ce donjon n'est pas dans la liste des donjons.",
	["That goal could not be set."] = "Cet objectif n'a pas pu être fixé.",
	["That is not a journal code. Look for !EUJ1!, FJ2: or FJ1: at the start."] = "Ce n'est pas un code de journal. Cherchez !EUJ1!, FJ2: ou FJ1: au début.",
	["That is one of your goals already."] = "C'est déjà l'un de vos objectifs.",
	["That item does not go in an equipment slot."] = "Cet objet ne va dans aucun emplacement d'équipement.",
	["That item does not go in this slot."] = "Cet objet ne va pas dans cet emplacement.",
	["That quest chain is not in the quest data."] = "Cette chaîne de quêtes n'est pas dans les données de quêtes.",
	["The %s page is switched off on the Loot Guide settings page."] = "La page %s est désactivée sur la page de réglages du Loot Guide.",
	["the address to report problems"] = "l’adresse où signaler les problèmes",
	["The adventurer's log: plain past tense, places and levels first."] = "Le carnet de l'aventurier : passé simple, lieux et niveaux d'abord.",
	["The Alts module stays off while %s is loaded, so only this character is known."] = "Le module Personnages reste désactivé tant que %s est chargé, donc seul ce personnage est connu.",
	["The Argent Dawn sends you to Naxxramas once you are Honored or better; each rank makes the way in cheaper."] = "L'Aube d'argent vous envoie à Naxxramas dès que vous êtes Honoré ou mieux ; chaque rang rend l'entrée moins chère.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on first."] = "L'onglet Accès se trouve dans le Loot Guide. Activez d'abord le Loot Guide.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on to use it."] = "L'onglet Accès se trouve dans le Loot Guide. Activez le Loot Guide pour l'utiliser.",
	["The backup is merged into your journal."] = "La sauvegarde est fusionnée dans votre journal.",
	["The best gear you can get for your spec and level, your filter and stat order, and two plan sets of your own."] = "Le meilleur équipement que vous pouvez obtenir pour votre spécialisation et votre niveau, votre filtre et votre ordre des caractéristiques, et deux ensembles du plan à vous.",
	["The best idea for right now and why it is here. A dungeon opens as a trip plan: the quests to pick up first, getting in, inside, and afterwards. Every button only shows you the way."] = "La meilleure idée du moment et pourquoi elle est là. Un donjon s'ouvre comme un plan de trajet : les quêtes à prendre d'abord, l'entrée, l'intérieur et la suite. Chaque bouton ne fait que vous montrer le chemin.",
	["The best item per slot from your list, what you wear, your two plan sets and your wishlist by slot. Click a slot to pick something else."] = "Le meilleur objet par emplacement de votre liste, ce que vous portez, vos deux ensembles du plan et votre liste de souhaits par emplacement. Cliquez sur un emplacement pour choisir autre chose.",
	["The best items on your list for your spec and the plan phase, one per slot. The number is the gain over what you wear."] = "Les meilleurs objets de votre liste pour votre spécialisation et la phase du plan, un par emplacement. Le nombre est le gain par rapport à ce que vous portez.",
	["The card joins the suggestions again."] = "La carte rejoint de nouveau les suggestions.",
	["The cards you put away. They come back at your next level or after 24 hours."] = "Les cartes que vous avez rangées. Elles reviennent à votre prochain niveau ou après 24 heures.",
	["The cards you sent off with Not now, with Bring back."] = "Les cartes écartées avec Pas maintenant, avec Ramener.",
	["The cards you sent off with Not now."] = "Les cartes écartées avec Pas maintenant.",
	["The chain as a chart: every step a box, lines to the steps that need it."] = "La chaîne en diagramme : chaque étape dans une case, des lignes vers les étapes qui en dépendent.",
	["The check could not start."] = "La vérification n'a pas pu démarrer.",
	["The check is running: %d of %d quests asked. %s stops it."] = { one = "Vérification en cours : %d quête sur %d demandée. %s l'arrête.", other = "Vérification en cours : %d quêtes sur %d demandées. %s l'arrête." },
	["The client does not know where this entrance is."] = "Le client ne sait pas où se trouve cette entrée.",
	["The code is incomplete or damaged (%s). Copy all of it and paste it again."] = "Le code est incomplet ou abîmé (%s). Copiez-le en entier et collez-le à nouveau.",
	["The code is incomplete or damaged. Copy all of it and paste it again."] = "Le code est incomplet ou abîmé. Copiez-le en entier et collez-le à nouveau.",
	["The commands and the address for problems. Pages, drop chances, the rating mode, alerts and the window look are in /eui > Loot Guide."] = "Les commandes et l'adresse pour les problèmes. Pages, chances de butin, mode d'évaluation, alertes et apparence de la fenêtre sont dans /eui > Loot Guide.",
	["The Crescent Key opens the doors of Dire Maul West and North; a boss in Dire Maul East drops it."] = "La Clé en croissant ouvre les portes de Hache-Tripes Ouest et Nord ; un boss de Hache-Tripes Est la donne.",
	["The data has no place on your map for this quest's giver."] = "Les données n’ont pas d’emplacement sur votre carte pour le donneur de cette quête.",
	["The database needs the loot data"] = "La base de données a besoin des données de butin",
	["The Defilers"] = "Les Profanateurs",
	["the details"] = "les détails",
	["the details below"] = "les détails ci-dessous",
	["The door opens at level %d."] = "La porte s'ouvre au niveau %d.",
	["The drop data comes with the Loot Guide. Turn the Loot Guide on to use it."] = "Les données de butin viennent avec le Loot Guide. Activez le Loot Guide pour vous en servir.",
	["The Drowned City"] = "The Drowned City",
	["the dummy cannot be stunned in a useful way"] = "le mannequin ne peut pas être étourdi utilement",
	["the dummy does not hit back"] = "le mannequin ne riposte pas",
	["the dungeon"] = "le donjon",
	["The EldoUI page and the place to report problems. Copy (Ctrl+C) and open them in your browser."] = "La page d'EldoUI et l'endroit où signaler les problèmes. Copiez (Ctrl+C) et ouvrez-les dans votre navigateur.",
	["The EldoUI project page and the address to report a wrong drop or a problem, ready to copy."] = "La page du projet EldoUI et l'adresse pour signaler un butin erroné ou un problème, prêtes à copier.",
	["The entrance is %s."] = "L'entrée se trouve %s.",
	["The Exodar"] = "L'Exodar",
	["The export did not work. The error is in the error list."] = "L'exportation n'a pas fonctionné. L'erreur est dans la liste des erreurs.",
	["The filters hide every answer."] = "Les filtres masquent toutes les réponses.",
	["The first faction that counts you as Honored."] = "La première faction qui vous considère comme Honoré.",
	["The first flight path you learned."] = "Le premier trajet aérien que vous avez appris.",
	["The first one on %s. Take its items or money from a mailbox."] = "Le premier expire le %s. Récupérez ses objets ou son argent dans une boîte aux lettres.",
	["The first page is still blank"] = "La première page est encore blanche",
	["The first quest you handed in with a group."] = "La première quête que vous avez rendue en groupe.",
	["The first rare you saw."] = "Le premier monstre rare que vous avez vu.",
	["The first step is open: %s."] = "La première étape est ouverte : %s.",
	["The first time you died. It happens to everyone."] = "La première fois que vous êtes mort. Ça arrive à tout le monde.",
	["The first time you entered a dungeon."] = "La première fois que vous êtes entré dans un donjon.",
	["The first time you entered a raid."] = "La première fois que vous êtes entré dans un raid.",
	["The game could not save it. Try your own screenshot key."] = "Le jeu n'a pas pu l'enregistrer. Essayez votre propre touche de capture.",
	["The game did not show your weapon skill, so the simulator used the usual skill for your level (5 per level)."] = "Le jeu n'a pas indiqué votre compétence d'arme, le simulateur utilise donc la compétence habituelle pour votre niveau (5 par niveau).",
	["The game does not list that faction for you yet. Check the spelling on your Reputation tab."] = "Le jeu ne liste pas encore cette faction pour vous. Vérifiez l'orthographe dans votre onglet Réputation.",
	["The game does not list this dungeon yet. It shows here as soon as it does."] = "Le jeu ne liste pas encore ce donjon. Il apparaîtra ici dès que ce sera le cas.",
	["The game does not report this step; it counts once the next one is done."] = "Le jeu ne signale pas cette étape ; elle compte dès que la suivante est faite.",
	["The game does not tell where this entrance is."] = "Le jeu ne dit pas où se trouve cette entrée.",
	["The game has no map picture for this place. Here are its bosses in order; click one for its loot."] = "Le jeu n'a pas d'image de carte pour ce lieu. Voici ses boss dans l'ordre ; cliquez sur l'un d'eux pour son butin.",
	["The game has no name for that place yet."] = "Le jeu n'a pas encore de nom pour ce lieu.",
	["The game has not sent this item's stats yet."] = "Le jeu n'a pas encore envoyé les caractéristiques de cet objet.",
	["the game marks it done"] = "le jeu la marque comme faite",
	["The game remembers %s quests you finished before the journal began."] = { one = "Le jeu se souvient de %s quête terminée avant le début du journal.", other = "Le jeu se souvient de %s quêtes terminées avant le début du journal." },
	["the game remembers it as done"] = "le jeu la retient comme faite",
	["The game shows this rare on your minimap right now."] = "Le jeu montre ce monstre rare sur votre minicarte en ce moment.",
	["The game's map could not place any creature camp. Open the world map once and come back."] = "La carte du jeu n'a pu placer aucun camp de créatures. Ouvrez une fois la carte du monde et revenez.",
	["The game's map says you are in this zone."] = "La carte du jeu indique que vous êtes dans cette zone.",
	["The game's own count of quests you completed."] = "Le décompte du jeu de vos quêtes terminées.",
	["The game's own count of your deaths."] = "Le décompte du jeu de vos morts.",
	["The gear you wear; each slot shows how much its Best in Slot item adds."] = "L'équipement que vous portez ; chaque emplacement montre ce que son objet Best in Slot apporte.",
	["The group finder could not open here."] = "La recherche de groupe n'a pas pu s'ouvrir ici.",
	["The group finder opens after combat."] = "La recherche de groupe s'ouvre après le combat.",
	["The guide goes back to following your zone when your map changes."] = "Le guide recommence à suivre votre zone quand votre carte change.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips."] = "Le guide a besoin des données de butin (l'addon EldoUI_LootData) ou de la liste de la recherche de donjon du jeu pour suggérer des trajets.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips. Quests in your log still show here."] = "Le guide a besoin des données de butin (l'addon EldoUI_LootData) ou de la liste de la recherche de donjon du jeu pour suggérer des trajets. Les quêtes de votre journal s'affichent quand même ici.",
	["The Hall of Thanes"] = "The Hall of Thanes",
	["The honor cost and PvP rank the item needs."] = "Le coût en honneur et le rang JcJ que l'objet demande.",
	["The import is undone."] = "L'importation est annulée.",
	["The instance page with every boss, its quests and its trash loot."] = "La page de l'instance avec chaque boss, ses quêtes et le butin de ses monstres.",
	["The item; its color is its quality."] = "L'objet ; sa couleur indique sa qualité.",
	["the items that fit this slot"] = "les objets qui vont dans cet emplacement",
	["The items you see this boss drop are added here."] = "Les objets que vous voyez ce boss laisser tomber s'ajoutent ici.",
	["The journal as a readable document, by chapter, with goals, notes and quests. Companion names are left out."] = "Le journal comme document lisible, par chapitre, avec objectifs, notes et quêtes. Les noms des compagnons sont omis.",
	["The journal as a web page (HTML). Save it as a .html file, open it in a browser and print it to PDF. Opened outside the game it loads its fonts from Google Fonts."] = "Le journal en page web (HTML). Enregistrez-le dans un fichier .html, ouvrez-le dans un navigateur et imprimez-le en PDF. Ouvert hors du jeu, il charge ses polices depuis Google Fonts.",
	["The journal as plain text, by chapter."] = "Le journal en texte brut, par chapitre.",
	["The journal begins in %s"] = "Le journal commence à %s",
	["The journal has no company by that name."] = "Le journal n'a aucun compagnon de ce nom.",
	["The journal has not been here yet."] = "Le journal n'est pas encore venu ici.",
	["The journal is not ready yet. Try again in a moment."] = "Le journal n'est pas encore prêt. Réessayez dans un instant.",
	["The journal of %s, saved %s."] = "Le journal de %s, enregistré %s.",
	["The journal shows what the game and your other EldoUI modules wrote down. Nothing is guessed."] = "Le journal montre ce que le jeu et vos autres modules EldoUI ont noté. Rien n'est deviné.",
	["The journal waits for the end of combat"] = "Le journal attend la fin du combat",
	["The Journal window's dark page and the EldoUI Book, the Storyteller detail with keepsakes, the tracker under your quests and moments in the alert lane."] = "La page sombre de la fenêtre Journal et le Livre EldoUI, le détail Conteur avec souvenirs, le suivi sous vos quêtes et les moments dans la file des alertes.",
	["The Journal window's own dark page with the accent color."] = "La page sombre propre à la fenêtre Journal, avec la couleur d'accent.",
	["The journal's own rows: short, exact, with digits."] = "Les lignes propres au journal : courtes, exactes, avec des chiffres.",
	["The journal's pages are switched off or still loading."] = "Les pages du journal sont désactivées ou encore en chargement.",
	["The Journey's day view on the day you last played."] = "La vue par jour du Voyage sur le dernier jour où vous avez joué.",
	["The Key to the City opens the service gate of Stratholme; a boss inside drops it."] = "La Clé de la ville ouvre la porte de service de Stratholme ; un boss à l'intérieur la donne.",
	["The last one you had open"] = "La dernière ouverte",
	["The last run is outdated: your level, gear, talents or list changed."] = "Le dernier calcul est obsolète : votre niveau, équipement, talents ou liste ont changé.",
	["The League of Arathor"] = "La Ligue d'Arathor",
	["The level log was off for these levels."] = "L'historique des niveaux était désactivé pour ces niveaux.",
	["The level of the target dummy. Bosses are three levels above you: more misses, glancing blows and resists."] = "Le niveau du mannequin d'entraînement. Les boss ont trois niveaux de plus que vous : plus d'échecs, de coups érafles et de résistances.",
	["The light part is rested experience: kills give double experience until it is used up."] = "La partie claire est l'expérience de repos : les victimes rapportent le double d'expérience jusqu'à ce qu'elle soit épuisée.",
	["The line is in the chat box. Press Enter to send it, or Escape to drop it."] = "La ligne est dans la zone de saisie. Appuyez sur Entrée pour l'envoyer, ou Échap pour l'abandonner.",
	["The list on the left leaves out attunements you have finished."] = "La liste de gauche omet les accès que vous avez terminés.",
	["The long chain of Anachronos and the three dragonflights that opens the gates of Ahn'Qiraj."] = "La longue chaîne d'Anachronos et des trois vols de dragons qui ouvre les portes d'Ahn'Qiraj.",
	["The long chain through Stormwind and Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "La longue chaîne à travers Hurlevent et le pic Rochenoire se termine par l'Amulette Flammedrake dont vous avez besoin pour le Repaire d'Onyxia.",
	["the loot"] = "le butin",
	["The loot data does not list where this recipe comes from."] = "Les données de butin ne disent pas d'où vient cette recette.",
	["The loot data has no place on your map for this."] = "Les données de butin n'ont pas de lieu sur votre carte pour cela.",
	["The loot data has no rares or named creatures for the zone you are in. Pick a zone on the left."] = "Les données de butin n'ont pas de monstres rares ni de créatures nommées pour la zone où vous êtes. Choisissez une zone à gauche.",
	["The loot data lists no bosses here."] = "Les données de butin ne listent aucun boss ici.",
	["The loot data lists no crafts for this profession."] = "Les données de butin ne listent aucune recette pour ce métier.",
	["The loot data lists no factions for your side."] = "Les données de butin ne listent aucune faction pour votre camp.",
	["The loot data lists no factions of the other side."] = "Les données de butin ne listent aucune faction de l’autre camp.",
	["The loot data lists no rewards for this faction."] = "Les données de butin ne listent aucune récompense pour cette faction.",
	["The loot data lists no vendors, quest rewards or drops for this event."] = "Les données de butin ne listent aucun marchand, récompense de quête ou butin pour cet événement.",
	["The Loot Guide opens out of combat."] = "Le Loot Guide s'ouvre hors combat.",
	["The Loot Guide stays off while %s is loaded."] = "Le Loot Guide reste désactivé tant que %s est chargé.",
	["The lowest quality a find needs to be written on the Journey. Changing it on a preset turns it into Custom."] = "La qualité minimale qu'une trouvaille doit avoir pour être notée dans le Voyage. La modifier sur un préréglage le passe en Personnalisé.",
	["The mouse wheel turns the pages too."] = "La molette de la souris tourne aussi les pages.",
	["The next open step of each attunement and key."] = "La prochaine étape ouverte de chaque accès et de chaque clé.",
	["The next step's quest giver on the map and toasts as you go."] = "Le donneur de quête de l'étape suivante sur la carte et des notifications en chemin.",
	["The Night ledger Book in smaller text, short chapters and a slim tracker. Row size stays the Loot Guide's own setting."] = "Le Livre Registre de nuit en texte plus petit, chapitres courts et suivi fin. La taille des lignes reste le réglage propre du Loot Guide.",
	["The numbers come from many short fights with random rolls. The ± range shows how sure they are (95 %)."] = "Les chiffres viennent de nombreux combats courts avec des jets aléatoires. La plage ± montre leur fiabilité (95 %).",
	["The oldest %d are kept as counts on their levels."] = { one = "Le plus ancien (%d) est gardé comme compte sur son niveau.", other = "Les %d plus anciens sont gardés comme comptes sur leurs niveaux." },
	["The oldest goes when a new one would pass this. The newest copy from before an EldoUI update has a slot of its own and is always kept."] = "Le plus ancien disparaît quand un nouveau dépasserait cette limite. La copie la plus récente d'avant une mise à jour d'EldoUI a sa propre place et est toujours conservée.",
	["The order your spec values stats in. Drag to change it."] = "L'ordre dans lequel votre spécialisation valorise les caractéristiques. Faites glisser pour le changer.",
	["The page the window shows when you open it outside a dungeon. The gear holds a switch for each page and the Catalog's settings."] = "La page que la fenêtre affiche quand vous l'ouvrez hors d'un donjon. L'engrenage contient un interrupteur pour chaque page et les réglages du Catalogue.",
	["the page you left, even inside a dungeon"] = "la page que vous avez quittée, même dans un donjon",
	["The pages of My Adventure on the Journal window's own dark panel, or on parchment with dark ink. The Book and the character card keep their own Book look."] = "Les pages de Mon aventure sur le panneau sombre propre à la fenêtre Journal, ou sur parchemin à l'encre sombre. Le Livre et la carte de personnage gardent leur propre apparence de Livre.",
	["The people you grouped with last first."] = "Les personnes avec qui vous avez été groupé le plus récemment d'abord.",
	["The people you met and grouped with."] = "Les personnes que vous avez rencontrées et avec qui vous avez été groupé.",
	["The people you spent the most time with first."] = "Les personnes avec qui vous avez passé le plus de temps d'abord.",
	["The people you traveled with: time together and how it was spent, dungeons and quests together, and your notes on them."] = "Les personnes avec qui vous avez voyagé : temps passé ensemble et comment, donjons et quêtes ensemble, et vos notes sur elles.",
	["The places you came to last first."] = "Les lieux où vous êtes venu le plus récemment d'abord.",
	["The places you spent the most time in first."] = "Les lieux où vous avez passé le plus de temps d'abord.",
	["The planner is already empty."] = "Le planificateur est déjà vide.",
	["The planner is empty."] = "Le planificateur est vide.",
	["The PvP planner works out weeks from this. Leave 0 to use what you earned in recent weeks."] = "Le planificateur JcJ calcule les semaines à partir de cela. Laissez 0 pour utiliser ce que vous avez gagné ces dernières semaines.",
	["The quest chains come from EldoUI_LootData, which loads a few seconds after login."] = "Les chaînes de quêtes viennent d'EldoUI_LootData, qui se charge quelques secondes après la connexion.",
	["The quest giver is %s."] = "Le donneur de quête se trouve %s.",
	["The quest giver's exclamation mark right of the bar, like the game's quest icon."] = "Le point d’exclamation du donneur de quête à droite de la barre, comme l’icône de quête du jeu.",
	["The quest givers are %s."] = "Les donneurs de quête se trouvent %s.",
	["The quest tracker leaves room at its bottom for the journal tracker. With Questie, the journal tracker sits right under Questie's list."] = "Le suivi des quêtes laisse de la place en bas pour le suivi du journal. Avec Questie, le suivi du journal se place juste sous la liste de Questie.",
	["The quests for this instance with your status: open, done or locked."] = "Les quêtes de cette instance avec votre état : ouverte, faite ou verrouillée.",
	["The quests you archived, with Restore."] = "Les quêtes que vous avez archivées, avec Restaurer.",
	["The reminder stays and shows each time, instead of once."] = "Le rappel reste et s'affiche à chaque fois, au lieu d'une seule.",
	["The reputation the item needs, red while you are below it."] = "La réputation que l'objet demande, en rouge tant que vous êtes en dessous.",
	["The road is waiting. Every zone you visit gets a card."] = "La route vous attend. Chaque zone que vous visitez reçoit une carte.",
	["The role they had when they sent it."] = "Le rôle qu'ils avaient quand ils l'ont envoyé.",
	["The same fights (same dice) for every set, so the differences are steadier than the totals."] = "Les mêmes combats (les mêmes dés) pour chaque ensemble, donc les écarts sont plus fiables que les totaux.",
	["The Seal of Ascension opens the doors of Upper Blackrock Spire for your whole group."] = "Le Sceau d'ascension ouvre les portes du Sommet du pic Rochenoire pour tout votre groupe.",
	["The search index is built out of combat. Try again in a moment."] = "L'index de recherche se construit hors combat. Réessayez dans un instant.",
	["The search looks through the %s table."] = "La recherche porte sur le tableau %s.",
	["The section My Adventure opens on: Today, a page you pick (Next trips, Journey, Book, Story so far, Keepsakes, Places, Quests, Fellowship, Goals or Notes), or the last one you had open."] = "La section sur laquelle Mon aventure s'ouvre : Aujourd'hui, une page de votre choix (Prochains trajets, Voyage, Livre, L'histoire jusqu'ici, Souvenirs, Lieux, Quêtes, Compagnie, Objectifs ou Notes), ou la dernière ouverte.",
	["The section you came back from. Alt+Right does the same."] = "La section d'où vous revenez. Alt+Droite fait de même.",
	["The section you had open before. Alt+Left or Backspace does the same."] = "La section ouverte juste avant. Alt+Gauche ou Retour arrière fait de même.",
	["The set an item is part of (owned of total) and what a token buys."] = "L'ensemble dont fait partie un objet (possédé sur total) et ce qu'un jeton achète.",
	["The set bonuses show once the game has the pieces' details (hover a piece once)."] = "Les bonus d'ensemble s'affichent dès que le jeu a les détails des pièces (survolez une pièce une fois).",
	["The set is shared with the Best in Slot page. This can't be undone."] = "L'ensemble est partagé avec la page Best in Slot. Cette action est irréversible.",
	["The Shadowforge Key opens the gates deeper in Blackrock Depths."] = "La Clé ombreforge ouvre les portes plus profondes des Profondeurs de Rochenoire.",
	["The Shapers Terrace"] = "The Shapers Terrace",
	["The simulation is done."] = "La simulation est terminée.",
	["The simulator could not start."] = "Le simulateur n'a pas pu démarrer.",
	["The simulator folder EldoUI_LootSim is not installed. It comes with EldoUI: put it next to the EldoUI folder in Interface\\AddOns."] = "Le dossier du simulateur EldoUI_LootSim n'est pas installé. Il est fourni avec EldoUI : placez-le à côté du dossier EldoUI dans Interface\\AddOns.",
	["The simulator found no damage spells it can use yet."] = "Le simulateur n'a pas encore trouvé de sorts de dégâts qu'il peut utiliser.",
	["The simulator has no model for your class."] = "Le simulateur n'a pas de modèle pour votre classe.",
	["The simulator has no numbers for this item yet."] = "Le simulateur n'a pas encore de chiffres pour cet objet.",
	["The simulator has no stats for these items, so sets with them are not simulated: "] = "Le simulateur n'a pas de caractéristiques pour ces objets, donc les ensembles qui les contiennent ne sont pas simulés : ",
	["The simulator runs out of combat. Try again when the fight is over."] = "Le simulateur tourne hors combat. Réessayez quand le combat sera fini.",
	["The Skeleton Key opens the gates of Scholomance."] = "La Clé squelette ouvre les portes de la Scholomance.",
	["The sound that plays with a wishlist alert."] = "Le son joué avec une alerte de liste de souhaits.",
	["The step is %s."] = "L'étape se trouve %s.",
	["The step is ready to hand in."] = "L'étape est prête à être rendue.",
	["the story of this quest"] = "l’histoire de cette quête",
	["The suggestions again."] = "De nouveau les suggestions.",
	["The tab lists attunements, keys and dungeon quests once the quest data is loaded."] = "L'onglet liste les accès, les clés et les quêtes de donjon dès que les données de quêtes sont chargées.",
	["The tavern song: warm and vivid, never false."] = "La chanson de taverne : chaleureuse et vivante, jamais fausse.",
	["The tour runs out of combat."] = "La visite se fait hors combat.",
	["The view the Overview button opens first."] = "La vue que le bouton Vue d'ensemble ouvre d'abord.",
	["The Warlord's Command chain through Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "La chaîne Les ordres du seigneur de guerre à travers le pic Rochenoire se termine par l'Amulette Flammedrake dont vous avez besoin pour le Repaire d'Onyxia.",
	["The whole Book in this tone as plain text, in a copy box."] = "Tout le Livre dans ce ton en texte brut, dans une zone de copie.",
	["The whole journal as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Tout le journal en un seul code, à garder ou à coller sur un autre PC. Rien n'est envoyé nulle part.",
	["The whole story in this tone as plain text, in a copy box."] = "Toute l'histoire dans ce ton en texte brut, dans une zone de copie.",
	["The whole story with headings, for a website, a forum, or Discord."] = "Toute l'histoire avec des titres, pour un site web, un forum ou Discord.",
	["The window lets the game show through a little. How much: General > Panel opacity. Drag the window's corner grip to change its size."] = "La fenêtre laisse un peu voir le jeu au travers. Dans quelle mesure : General > Panel opacity. Faites glisser la poignée du coin de la fenêtre pour changer sa taille.",
	["The zone is %d-%d; you are level %d."] = "La zone est %d-%d ; vous êtes niveau %d.",
	["The zone list is built out of combat. It shows once the fight is over."] = "La liste des zones se construit hors combat. Elle s’affiche une fois le combat terminé.",
	["The Zones section lives in the Loot Guide. Turn the Loot Guide on to use it."] = "La section Zones fait partie du Loot Guide. Activez le Loot Guide pour vous en servir.",
	["There is no import to undo."] = "Aucune importation à annuler.",
	["There is no journal to back up yet."] = "Il n'y a pas encore de journal à sauvegarder.",
	["There is no journal to export yet."] = "Il n'y a pas encore de journal à exporter.",
	["There is no live position inside dungeons."] = "Il n'y a pas de position en direct dans les donjons.",
	["They come back at your next level or after 24 hours."] = "Elles reviennent à votre prochain niveau ou après 24 heures.",
	["They may be in another character's fellowship."] = "Ils sont peut-être dans la compagnie d'un autre personnage.",
	["They were level %s."] = "Ils étaient niveau %s.",
	["Things you want to work towards. Their progress moves by itself as the game reports it."] = "Les buts vers lesquels vous voulez avancer. Leur progression avance toute seule à mesure que le jeu la signale.",
	["This backup is still being written. Try again in a moment."] = "Cette sauvegarde est encore en cours d'écriture. Réessayez dans un instant.",
	["This can't be undone."] = "Impossible d’annuler.",
	["This client"] = "Ce client",
	["This client cannot set a map pin."] = "Ce client ne peut pas placer de repère de carte.",
	["This client has no group finder window."] = "Ce client n'a pas de fenêtre de recherche de groupe.",
	["This code contains only recent changes. Merge adds them to your journal and keeps your existing entries."] = "Ce code ne contient que des modifications récentes. Fusionner les ajoute à votre journal et conserve vos entrées existantes.",
	["This game client cannot answer quest questions."] = "Ce client de jeu ne peut pas répondre aux questions sur les quêtes.",
	["This game client does not tell add-ons about poisons, oils and other temporary weapon enchants, so they are not counted."] = "Ce client de jeu n'indique pas aux addons les poisons, huiles et autres enchantements temporaires d'arme, ils ne sont donc pas comptés.",
	["This is how wishlist alerts look."] = "Voici à quoi ressemblent les alertes de liste de souhaits.",
	["this is not a Best in Slot string"] = "ce n'est pas un texte Best in Slot",
	["this is not a wishlist string"] = "ce n'est pas un texte de liste de souhaits",
	["This list is already empty."] = "Cette liste est déjà vide.",
	["This list shows the factions you have met. Show all factions to see every faction's rewards."] = "Cette liste montre les factions que vous avez rencontrées. Afficher toutes les factions montre les récompenses de chaque faction.",
	["This page shows where to go next and what is waiting for you."] = "Cette page montre où aller ensuite et ce qui vous attend.",
	["This place cannot be shown on your map."] = "Ce lieu ne peut pas être affiché sur votre carte.",
	["This place has no dungeon map."] = "Ce lieu n'a pas de carte de donjon.",
	["This place has no point on your map yet."] = "Ce lieu n'a pas encore de point sur votre carte.",
	["This session"] = "Cette session",
	["Thorium Brotherhood"] = "Confrérie du thorium",
	["Thunder Bluff"] = "Les Pitons-du-Tonnerre",
	["check it off"] = "le cocher",
	["check it off yourself"] = "cochez-le vous-même",
	["Checked sets run in the next Sets run, all in the same fights."] = "Les ensembles cochés passent dans la prochaine simulation des ensembles, tous dans les mêmes combats.",
	["Tier sets"] = "Ensembles de palier",
	["Timbermaw Hold"] = "Les Grumegueules",
	["Time"] = "Temps",
	["time here"] = "temps ici",
	["Time here"] = "Temps ici",
	["Time in the same group, away from keyboard not counted."] = "Temps dans le même groupe, absences du clavier non comptées.",
	["Time played at each level, from the level log."] = "Temps de jeu à chaque niveau, d'après le journal des niveaux.",
	["Time together"] = "Temps ensemble",
	["Time you spent here, away from keyboard not counted."] = "Le temps passé ici, absences du clavier non comptées.",
	["to %s"] = "à %s",
	["to %s, %s"] = "à %s, %s",
	["To level"] = "Jusqu'au niveau",
	["to pick up"] = "à prendre",
	["toast"] = "notification",
	["Toast (Alerts and Banners)"] = "Notification (Alerts and Banners)",
	["Toast, else loot toast, else chat"] = "Notification, sinon notification de butin, sinon discussion",
	["Today"] = "Aujourd'hui",
	["Together"] = "Ensemble",
	["Tokens"] = "Insignes",
	["Tokens come from EldoUI_LootData. Install it next to EldoUI to list them."] = "Les insignes viennent d'EldoUI_LootData. Installez-le à côté d'EldoUI pour les lister.",
	["Tokens shows what each raid token buys for a class."] = "Insignes montre ce que chaque insigne de raid achète pour une classe.",
	["Tone"] = "Ton",
	["too costly for its gain"] = "trop coûteux pour son gain",
	["too low for it"] = "niveau trop bas",
	["Too low level"] = "Niveau trop bas",
	["too slow to cast on a dummy"] = "trop lent à lancer sur un mannequin",
	["Tooltip line settings"] = "Réglages des lignes d'infobulle",
	["Tooltip: %s"] = "Infobulle : %s",
	["Tooltips"] = "Infobulles",
	["Tooltips and map"] = "Infobulles et carte",
	["total %s"] = "total %s",
	["Total: %s %s"] = "Total : %s %s",
	["totems are not modeled"] = "les totems ne sont pas modélisés",
	["Track"] = "Suivre",
	["Tracker and buttons"] = "Suivi et boutons",
	["Tracker height"] = "Hauteur du suivi",
	["Trainer"] = "Maître",
	["trainer"] = "maître",
	["Trainer: %s %d"] = "Maître : %s %d",
	["Trash and zone drops"] = "Butin des trashs et de la zone",
	["Traveling"] = "En voyage",
	["Trinket"] = "Bijou",
	["try on"] = "essayer",
	["Try on"] = "Essayer",
	["Try on set"] = "Essayer l'ensemble",
	["Turbo (16 ms a frame)"] = "Turbo (16 ms par image)",
	["Turn Forever Journal off in the AddOns list and reload, so the two journals do not both write."] = "Désactivez Forever Journal dans la liste des AddOns et rechargez, pour que les deux journaux n'écrivent pas tous les deux.",
	["Turn in: %s"] = "Rendre : %s",
	["Turn it on"] = "L'activer",
	["Turn on Alts"] = "Activer Personnages",
	["Turn on Attunements to set this goal."] = "Activez Accès pour fixer cet objectif.",
	["Turn on Blizzard UI > Objective / quest tracker > Move and scale to keep the quest list clear of the journal tracker."] = "Activez Blizzard UI > Objective / quest tracker > Move and scale pour garder la liste de quêtes à l’écart du suivi du journal.",
	["Turn on sharing"] = "Activer le partage",
	["Turn on sharing to ask guild and group members who use EldoUI for their attunements and to send yours. Nothing is sent until you click Ask or Send mine."] = "Activez le partage pour demander leurs accès aux membres de la guilde et du groupe qui utilisent EldoUI et pour envoyer les vôtres. Rien n'est envoyé tant que vous ne cliquez pas sur Demander ou Envoyer les miens.",
	["Turn on the Alts module to see the attunements of your other characters here."] = "Activez le module Personnages pour voir ici les accès de vos autres personnages.",
	["Turn on the Loot Guide"] = "Activer le Loot Guide",
	["Turn on the Nameplates module first."] = "Activez d’abord le module Nameplates.",
	["Turn-in"] = "Rendu",
	["Turns Hide finished off."] = "Désactive Masquer les terminés.",
	["Turns off My level only."] = "Désactive Mon niveau seulement.",
	["Turns on Share with guild and group (Attunements settings)."] = "Active Partager avec la guilde et le groupe (réglages des Accès).",
