	["Waiting: addon messages are paused here"] = "En attente : les messages d'addon sont en pause ici",
	["Walks through every page of the Loot Guide again, and shows the small tours of the filter, dungeon map and simulator again too."] = "Repasse par chaque page du Loot Guide et remontre aussi les petites visites du filtre, de la carte du donjon et du simulateur.",
