	["Wears the set on show. Drag to turn it, mouse wheel to zoom."] = "Porte l'ensemble affiché. Faites glisser pour le tourner, molette pour zoomer.",
	["Welcome card put away."] = "Carte de bienvenue rangée.",
	["Welcome to the Loot Guide"] = "Bienvenue dans le Loot Guide",
	["Well rested"] = "Bien reposé",
	["Well rested (%d%% of a level): a good time for a dungeon."] = "Bien reposé (%d%% d'un niveau) : un bon moment pour un donjon.",
	["What do you want to do?"] = "Que voulez-vous faire ?",
	["What each faction sells or gives at every standing, how far you are from it and which rewards are upgrades for you."] = "Ce que chaque faction vend ou donne à chaque niveau de réputation, à quelle distance vous en êtes et quelles récompenses sont des améliorations pour vous.",
	["What each raid token or turn-in item buys for a class."] = "Ce que chaque insigne de raid ou objet à rendre achète pour une classe.",
	["What happened here"] = "Ce qui s'est passé ici",
	["What I wear"] = "Ce que je porte",
	["What is ahead"] = "Ce qui vous attend",
	["What is left are raids, attunements, and reputation. Next trips shows them once you turn on raids, and the Attunements page has every key."] = "Il reste les raids, les accès et la réputation. Prochains trajets les montre dès que vous activez les raids, et la page Accès a chaque clé.",
	["What is left are raids, attunements, and reputation. Nothing else fits right now; put-away cards come back after 24 hours."] = "Il reste les raids, les accès et la réputation. Rien d'autre ne convient pour l'instant ; les cartes rangées reviennent après 24 heures.",
	["What opens at level %d"] = "Ce qui s'ouvre au niveau %d",
	["What opens at the next level"] = "Ce qui s'ouvre au prochain niveau",
	["What shows"] = "Ce qui s’affiche",
	["What the game's quest lines report on this map. Copy it (Ctrl+C) and send it to EldoUI's authors."] = "Ce que les suites de quêtes du jeu signalent sur cette carte. Copiez-le (Ctrl+C) et envoyez-le aux auteurs d'EldoUI.",
	["What the item adds over what you wear, with your stat priority."] = "Ce que l'objet apporte par rapport à ce que vous portez, selon votre priorité de caractéristiques.",
	["What the journal writes down, the look of its pages, and how the ideas are ranked. /eui tour journal shows this tour again."] = "Ce que le journal note, l'apparence de ses pages et le classement des idées. /eui tour journal remontre cette visite.",
	["What the journal wrote down since you last logged out."] = "Ce que le journal a noté depuis votre dernière déconnexion.",
	["What the pages show"] = "Ce que montrent les pages",
	["What the tab has loaded. Chains come from EldoUI_LootData (Classic values; WoW: Forever may differ)."] = "Ce que l'onglet a chargé. Les suites viennent d'EldoUI_LootData (valeurs de Classic ; WoW: Forever peut différer).",
	["What was read"] = "Ce qui a été lu",
	["What would you like to work towards?"] = "Vers quoi voulez-vous avancer ?",
	["What you wear, Best in Slot and your plan sets compared as DPS from the same fights."] = "Ce que vous portez, Best in Slot et vos ensembles prévus comparés en DPS sur les mêmes combats.",
	["When a backup is taken by itself, 8 seconds after you log in and out of combat."] = "Quand une sauvegarde est faite d'elle-même, 8 secondes après la connexion et hors combat.",
	["When someone asks"] = "Quand quelqu'un demande",
	["When this note should show again as a reminder. It picks one from what you write until you choose yourself."] = "Quand cette note doit réapparaître comme rappel. Elle en choisit un d'après ce que vous écrivez jusqu'à ce que vous choisissiez vous-même.",
	["When you apply a layout preset, the Book takes the look of the style that fits it: EldoUI, Storybook or Compact. What the journal shows is kept."] = "Quand vous appliquez un préréglage de disposition, le Livre prend l'apparence du style qui lui correspond : EldoUI, Livre d'histoires ou Compact. Ce que le journal montre est gardé.",
	["When you enter %s"] = "Quand vous entrez dans %s",
	["When you open a profession"] = "Quand vous ouvrez un métier",
	["When you reach level %d"] = "Quand vous atteignez le niveau %d",
	["Where"] = "Où",
	["Where it began"] = "Là où tout a commencé",
	["where it drops"] = "où il tombe",
	["Where next"] = "Où aller ensuite",
	["Where recipes come from needs EldoUI_LootData. Install it next to EldoUI to see trainers, vendors, drops and quests."] = "L'origine des recettes demande EldoUI_LootData. Installez-le à côté d'EldoUI pour voir maîtres, marchands, butins et quêtes.",
	["Where the alert shows. Every alert also writes one chat line so you can read it later."] = "Où l'alerte s'affiche. Chaque alerte écrit aussi une ligne de discussion pour que vous puissiez la relire plus tard.",
	["Where the icon sits on the plate. Right of the bar comes after the elite and quest icons."] = "Où l’icône se place sur la barre. À droite de la barre vient après les icônes d’élite et de quête.",
	["Where the item drops and how often, and the vendors that sell it with the cost. Hold Shift for more sources and the drops you saw yourself."] = "Où l'objet tombe et à quelle fréquence, et les marchands qui le vendent avec le prix. Maintenez Maj pour plus de sources et les butins que vous avez vus vous-même.",
	["where the loot data comes from"] = "d'où viennent les données de butin",
	["Where this comes from"] = "D'où cela vient",
	["Where to go"] = "Où aller",
	["Where to go next and why: dungeons with their quests, quests that fit your level, attunement steps, and zones to explore."] = "Où aller ensuite et pourquoi : donjons avec leurs quêtes, quêtes adaptées à votre niveau, étapes d'accès et zones à explorer.",
	["Where to go next, what is waiting for you, and what just happened."] = "Où aller ensuite, ce qui vous attend et ce qui vient de se passer.",
	["Where to go now and what you get there: the best dungeon for your level, your next upgrades and your best-in-slot progress."] = "Où aller maintenant et ce que vous y obtenez : le meilleur donjon pour votre niveau, vos prochaines améliorations et votre progression Best in Slot.",
