	["Your /played time, from the game."] = "Votre temps /played, d'après le jeu.",
	["Your active goals under the quest tracker. Click a to-do to check it."] = "Vos objectifs actifs sous le suivi des quêtes. Cliquez sur une tâche pour la cocher.",
	["Your active wishlist by slot. Click a slot to choose its main pick; the model wears the picks."] = "Votre liste de souhaits active par emplacement. Cliquez sur un emplacement pour choisir son choix principal ; le modèle porte les choix.",
	["Your active wishlist has no gear. Star items in the Journal or Search; they show here by slot."] = "Votre liste de souhaits active n'a pas d'équipement. Mettez une étoile aux objets dans le Journal ou la Recherche ; ils s'affichent ici par emplacement.",
	["Your Best in Slot run is outdated."] = "Votre simulation Best in Slot est dépassée.",
	["Your big moments as cards: first kills, epic finds, standings, mounts, and the moments you kept, with your firsts."] = "Vos grands moments en cartes : premières victoires, trouvailles épiques, réputations, montures et les moments que vous avez gardés, avec vos premières fois.",
	["Your big moments at these levels."] = "Vos grands moments à ces niveaux.",
	["Your character card"] = "Votre fiche de personnage",
	["Your character card as a few lines of text. Companion names are left out."] = "Votre fiche de personnage en quelques lignes de texte. Les noms des compagnons sont omis.",
	["Your character card as Markdown"] = "Votre fiche de personnage en Markdown",
	["Your character card on a dimmed screen, ready for your own screenshot key."] = "Votre fiche de personnage sur un écran assombri, prête pour votre propre touche de capture d'écran.",
	["Your character's journal, the first tab of this window: where to go next, what is waiting for you, and everything you have done."] = "Le journal de votre personnage, le premier onglet de cette fenêtre : où aller ensuite, ce qui vous attend et tout ce que vous avez fait.",
	["Your character's journal: what you did and where, keepsakes, goals, notes, attunements, and where to go next."] = "Le journal de votre personnage : ce que vous avez fait et où, souvenirs, objectifs, notes, accès et où aller ensuite.",
	["Your character's journal: where to go next, what is waiting for you, your goals and notes, and the story so far. /eui tour journal shows it part by part."] = "Le journal de votre personnage : où aller ensuite, ce qui vous attend, vos objectifs et notes, et l'histoire jusqu'ici. /eui tour journal le montre partie par partie.",
	["Your character's story in a few lines, with the level river, your numbers, the eras, and ways to share it."] = "L'histoire de votre personnage en quelques lignes, avec la rivière des niveaux, vos chiffres, les époques et des moyens de la partager.",
	["Your character's story in a few pages."] = "L'histoire de votre personnage en quelques pages.",
	["Your characters"] = "Vos personnages",
	["Your characters and how far each one is (Alts module)."] = "Vos personnages et où en est chacun (module Personnages).",
	["your class"] = "votre classe",
	["Your class (Sets for my class only), all classes or one other class."] = "Votre classe (Ensembles pour ma classe seulement), toutes les classes ou une autre classe.",
	["Your class can't use it"] = "Votre classe ne peut pas l'utiliser",
	["Your class can't use this"] = "Votre classe ne peut pas utiliser ceci",
	["Your DPS with what you wear, the damage of each ability, what one more point of each stat is worth, and what the simulator read."] = "Vos DPS avec ce que vous portez, les dégâts de chaque technique, ce que vaut un point de plus de chaque caractéristique et ce que le simulateur a lu.",
	["Your DPS: %.1f ± %.1f (estimate)"] = "Vos DPS : %.1f ± %.1f (estimation)",
	["Your factions with your standing. Pick one to see what it sells and gives at each standing."] = "Vos factions avec votre réputation. Choisissez-en une pour voir ce qu'elle vend et donne à chaque niveau.",
	["Your filters hide all %d drops."] = { one = "Vos filtres masquent %d butin.", other = "Vos filtres masquent les %d butins." },
	["Your filters hide every attunement. Show finished attunements?"] = "Vos filtres masquent tous les accès. Afficher les accès terminés ?",
	["Your first attunement step is open:"] = "Votre première étape d'accès est ouverte :",
	["Your first attunement step."] = "Votre première étape d'accès.",
	["Your first boss kill."] = "Votre première victoire sur un boss.",
	["Your first dungeon is waiting. These fit your level:"] = "Votre premier donjon vous attend. Ceux-ci conviennent à votre niveau :",
	["Your first epic find."] = "Votre première trouvaille épique.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for."] = "Votre première monture vient du vendeur de montures de votre race dès que vous avez le niveau et l'or demandés.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for. Meanwhile:"] = "Votre première monture vient du vendeur de montures de votre race dès que vous avez le niveau et l'or demandés. En attendant :",
	["Your first mount."] = "Votre première monture.",
	["Your Forever Journal history for this character is now in My Adventure (%s)."] = "L'historique de Forever Journal de ce personnage est maintenant dans Mon aventure (%s).",
	["Your gear is better for %s"] = "Votre équipement est meilleur pour %s",
	["Your group"] = "Votre groupe",
	["Your group is small for a %d-player dungeon."] = "Votre groupe est petit pour un donjon pour %d joueurs.",
	["Your hearthstone is set to %s."] = "Votre pierre de foyer est liée à %s.",
	["Your honor, marks and rank. Costs show once you have visited the vendor."] = "Votre honneur, vos marques et votre rang. Les coûts s'affichent dès que vous avez visité le marchand.",
	["Your journal"] = "Votre journal",
	["Your journal as it is now is backed up first either way."] = "Votre journal tel qu'il est maintenant est d'abord sauvegardé dans tous les cas.",
	["Your journal as it is now is backed up first."] = "Votre journal est d'abord sauvegardé dans son état actuel.",
	["Your journal is back as it was then."] = "Votre journal est revenu tel qu'il était alors.",
	["Your journal starts today"] = "Votre journal commence aujourd'hui",
	["Your last run took %s."] = "Votre dernière session a duré %s.",
	["Your level"] = "Votre niveau",
	["Your levels while you were grouped with them."] = "Vos niveaux pendant que vous étiez groupé avec eux.",
	["Your loot journal, Best in Slot planner and wishlist in one window. This short tour shows each part; Skip ends it, and Start tour on the settings page brings it back."] = "Votre journal de butin, votre planificateur Best in Slot et votre liste de souhaits dans une seule fenêtre. Cette courte visite montre chaque partie ; Passer la termine, et Commencer la visite sur la page des réglages la ramène.",
	["Your loot list"] = "Votre liste de butin",
	["Your name, or the pronoun you pick. Exports always use your name."] = "Votre nom, ou le pronom que vous choisissez. Les exports utilisent toujours votre nom.",
	["Your note"] = "Votre note",
	["Your note on \"%s\" (up to %d letters; empty removes it):"] = "Votre note sur « %s » (jusqu'à %d lettres ; vide la supprime) :",
	["Your note on them, kept in Player Notes and shown on their tooltip."] = "Votre note sur eux, gardée dans Notes de joueurs et affichée dans leur infobulle.",
	["Your note, from Player Notes"] = "Votre note, d'après Notes de joueurs",
	["Your note: %s"] = "Votre note : %s",
	["Your notes."] = "Vos notes.",
	["Your own level times show here once you have a few levels behind you."] = "Vos propres temps par niveau s'affichent ici dès que vous avez quelques niveaux derrière vous.",
	["your own list"] = "votre propre liste",
	["Your own plan. Click a slot to pick items; right-click the chip to rename it."] = "Votre propre plan. Cliquez sur un emplacement pour choisir des objets ; clic droit sur la pastille pour la renommer.",
	["Your own side's factions, or the other side's (to see what they get)."] = "Les factions de votre camp, ou celles de l'autre camp (pour voir ce qu'elles obtiennent).",
	["Your pet is not out. Call it and press Sim again."] = "Votre familier n'est pas sorti. Appelez-le et appuyez de nouveau sur Sim.",
	["Your plan sets are empty. Pick items for them on the Best in Slot page or in the Planner tab."] = "Vos ensembles prévus sont vides. Choisissez-leur des objets sur la page Best in Slot ou dans l'onglet Planificateur.",
	["Your plan sets are shared with the Best in Slot page. Rename them there."] = "Vos ensembles prévus sont partagés avec la page Best in Slot. Renommez-les là-bas.",
	["Your professions come first with your skill. Open your profession window once so known recipes and their colors show."] = "Vos métiers viennent en premier avec votre compétence. Ouvrez une fois votre fenêtre de métier pour que les recettes connues et leurs couleurs s'affichent.",
	["your quest log"] = "votre journal de quêtes",
	["Your quest log is empty"] = "Votre journal de quêtes est vide",
	["Your quest log is empty."] = "Votre journal de quêtes est vide.",
	["Your quest log now, with where and when you took each quest."] = "Votre journal de quêtes actuel, avec le lieu et le moment où vous avez pris chaque quête.",
	["Your quests here: %s."] = { one = "Votre quête ici : %s.", other = "Vos quêtes ici : %s." },
	["Your race can't use it"] = "Votre race ne peut pas l'utiliser",
	["Your runs"] = "Vos sessions",
	["Your runs here: first visit, time inside, bosses beaten, who came along, and what is still to do."] = "Vos sessions ici : première visite, temps à l'intérieur, boss vaincus, qui est venu et ce qui reste à faire.",
	["Your runs there"] = "Vos sessions là-bas",
	["Your screenshot key: %s."] = "Votre touche de capture d'écran : %s.",
	["Your sets are simulated. Open the Sets tab to compare them."] = "Vos ensembles sont simulés. Ouvrez l'onglet Ensembles pour les comparer.",
	["Your side"] = "Votre camp",
	["Your skill: %d"] = "Votre compétence : %d",
	["your spec"] = "votre spécialisation",
	["Your spec, the armor you wear and where gear may come from. This one list counts everywhere: For You, tooltips and roll advice."] = "Votre spécialisation, l'armure que vous portez et d'où l'équipement peut venir. Cette seule liste compte partout : Pour vous, infobulles et conseils de jet.",
	["Your story as it happened: chapters by level, day, or zone, with keepsakes, finds, and pinned notes."] = "Votre histoire telle qu'elle s'est passée : chapitres par niveau, jour ou zone, avec souvenirs, trouvailles et notes épinglées.",
	["Your story as Markdown"] = "Votre histoire en Markdown",
	["Your story as text"] = "Votre histoire en texte",
	["Your story chapter by chapter: levels, places, first kills, finds, and the people you met. Keepsakes and the story so far sit beside it."] = "Votre histoire chapitre par chapitre : niveaux, lieux, premières victoires, trouvailles et les gens rencontrés. Les souvenirs et l'histoire jusqu'ici sont à côté.",
	["Your story from level 1 to 60 as a book in chapters, in the tone you choose, with a cover for every part."] = "Votre histoire du niveau 1 à 60 comme un livre en chapitres, dans le ton choisi, avec une couverture pour chaque partie.",
	["Your story in chapters, page by page."] = "Votre histoire en chapitres, page par page.",
	["Your story in chapters, written from what the journal recorded."] = "Votre histoire en chapitres, écrite d'après ce que le journal a noté.",
	["Your story starts with the first thing the journal writes down."] = "Votre histoire commence par la première chose que le journal note.",
	["your talents"] = "vos talents",
	["Your target."] = "Votre cible.",
	["Your two plan sets (the same as on the Best in Slot page). Click a slot to pick an item or drop one from your bags."] = "Vos deux ensembles prévus (les mêmes que sur la page Best in Slot). Cliquez sur un emplacement pour choisir un objet ou déposez-en un depuis vos sacs.",
	["Your whole story, chapter by chapter."] = "Toute votre histoire, chapitre par chapitre.",
	["Your whole story, place by place."] = "Toute votre histoire, lieu par lieu.",
	["Your whole story, with the keepsakes in their place."] = "Toute votre histoire, avec les souvenirs à leur place.",
	["Your wishlist alerts you when the item drops."] = "Votre liste de souhaits vous alerte quand l'objet tombe.",
	["Your wishlist is empty"] = "Votre liste de souhaits est vide",
	["Zandalar Tribe"] = "Tribu Zandalar",
	["Zone"] = "Zone",
	["Zone Info"] = "Zone Info",
	["Zone list"] = "Liste des zones",
	["Zone map"] = "Carte locale",
	["Zone Quests"] = "Quêtes de zone",
	["Zone quests come from EldoUI_LootData. Install that folder next to EldoUI to see every zone; until then only the quests the game showed you are listed."] = "Les quêtes de zone viennent d’EldoUI_LootData. Installez ce dossier à côté d’EldoUI pour voir chaque zone ; d’ici là, seules les quêtes que le jeu vous a montrées sont listées.",
	["Zone: %s"] = "Zone : %s",
	["Zone: All"] = "Zone : toutes",
	["Zones"] = "Zones",
	["Zones and dungeons."] = "Zones et donjons.",
	["Zones and mobs"] = "Zones et monstres",
	["Zones for your level"] = "Zones pour votre niveau",
	["Zones for your level or all zones. The guide follows your zone until you click one."] = "Zones pour votre niveau ou toutes les zones. Le guide suit votre zone jusqu'à ce que vous en cliquiez une.",
	["Zones for your level, or every zone the loot data knows creatures for."] = "Zones pour votre niveau, ou chaque zone dont les données de butin connaissent les créatures.",
	["Zones with quests for your level that you have not done yet."] = "Zones avec des quêtes pour votre niveau que vous n'avez pas encore faites.",
	["Zoom in"] = "Zoomer",
	["Zoom out"] = "Dézoomer",
	["Zooms so the whole chain fits the window."] = "Zoome pour que toute la suite tienne dans la fenêtre.",
	["Zul'Gurub sets"] = "Ensembles de Zul'Gurub",
	["~%s to %d"] = "~%s jusqu'au niveau %d",
	["Drag to make the window bigger or smaller; the content follows. Ctrl+mouse wheel on the title bar zooms."] = "Faites glisser pour agrandir ou réduire la fenêtre ; le contenu suit. Ctrl+molette sur la barre de titre pour zoomer.",
	["Window size"] = "Taille de la fenêtre",
	["Opens at level %d in %s."] = "Disponible au niveau %d (%s).",
	["Opens at level %d with %s in %s."] = "S'ouvre au niveau %d auprès de %s (%s).",
	["Opens at level %d."] = "S'ouvre au niveau %d.",
	["It ends with %s."] = "Elle se termine par %s.",
	["Tracks whether you have the Dalaran Sewer Key. One key holder can open the gate for the group; you do not need to finish the dungeon quest first."] = "Indique si vous possédez la clé des égouts de Dalaran. Une seule personne avec la clé peut ouvrir la grille pour le groupe ; il n'est pas nécessaire de terminer d'abord la quête du donjon.",
	["%d more drops were not kept."] = { one = "%d objet de plus n'a pas été conservé.", other = "%d objets de plus n'ont pas été conservés." },
	["%s runs"] = { one = "%s sortie", other = "%s sorties" },
	["%s runs added to your journal."] = { one = "%s sortie ajoutée à votre journal.", other = "%s sorties ajoutées à votre journal." },
	["Accept merges them into this character's runs: nothing is lost, and a backup is taken first."] = "Accepter les fusionne avec les sorties de ce personnage : rien n'est perdu, et une sauvegarde est faite avant.",
	["An item"] = "Un objet",
	["Attunement lines on item and character tooltips have their own switches on the Tooltip page."] = "Les lignes d'accès dans les infobulles d'objet et de personnage ont leurs propres interrupteurs sur la page Infobulles.",
	["Attunements, keys and dungeon quest chains as a Loot Guide tab. Progress comes from your quest log, bags and reputation."] = "Accès, clés et suites de quêtes de donjon dans un onglet du Loot Guide. La progression vient de votre journal de quêtes, de vos sacs et de votre réputation.",
	["Backups are copies of this journal in your saved data. The game writes them to disk when you log out or /reload."] = "Les sauvegardes sont des copies de ce journal dans vos données enregistrées. Le jeu les écrit sur le disque quand vous vous déconnectez ou faites /reload.",
	["Backups of your runs"] = "Sauvegardes de vos sorties",
	["Classic: chances from Classic data; Forever may differ. Seen: what you looted yourself, with the number of kills (needs Mob and Loot Info)."] = "Classic : chances tirées des données Classic ; Forever peut différer. Vu : ce que vous avez ramassé vous-même, avec le nombre de créatures tuées (nécessite Infos créatures et butin).",
	["Copy a runs code"] = "Copier un code de sorties",
	["Creatures that can drop an item that starts a quest get a tooltip line and a small icon on their nameplate."] = "Les créatures qui peuvent laisser tomber un objet qui lance une quête reçoivent une ligne dans leur infobulle et une petite icône sur leur barre d'info.",
	["Delete this run?"] = "Supprimer cette sortie ?",
	["Every dungeon and raid run stays in your journal with who was in it. Its own code keeps them safe or moves them to another PC."] = "Chaque sortie en donjon et en raid reste dans votre journal avec ceux qui y étaient. Son propre code les garde en sécurité ou les déplace sur un autre PC.",
	["Every zone's quests in the Loot Guide's Catalog: how many you have done, what is left and who gives them."] = "Les quêtes de chaque zone dans le Catalogue du Loot Guide : combien vous en avez fait, ce qui reste et qui les donne.",
	["Everyone passed"] = "Tous ont passé",
	["For this character: your stat weights (fast, the same as the Upgrades arrows), or the simulator (DPS against a target dummy, run when you press Sim)."] = "Pour ce personnage : vos poids de caractéristiques (rapide, les mêmes que les flèches d'amélioration) ou le simulateur (DPS contre un mannequin d'entraînement, lancé quand vous appuyez sur Sim).",
	["Forget"] = "Oublier",
	["Forget this name?"] = "Oublier ce nom ?",
	["Green is done, the accent is in your quest log, yellow is available, gray is locked. An unreported step counts once the next is done."] = "Vert : terminé, couleur d'accent : dans votre journal de quêtes, jaune : disponible, gris : verrouillé. Une étape non signalée compte dès que la suivante est faite.",
	["Journal run backups of %s"] = "Sauvegardes des sorties du journal de %s",
	["Journal runs backup"] = "Sauvegarde des sorties du journal",
	["Journal runs of %s"] = "Sorties du journal de %s",
	["Load the runs of %s (saved %s) into this character?"] = "Charger les sorties de %s (sauvegardées %s) dans ce personnage ?",
	["Loads a runs code (!EUJR1!). You see what it holds, then Merge or Replace."] = "Charge un code de sorties (!EUJR1!). Vous voyez ce qu'il contient, puis Fusionner ou Remplacer.",
	["Loot Guide in EldoUI %s. %s opens the window, %s the simulator, %s lists every command."] = "Loot Guide dans EldoUI %s. %s ouvre la fenêtre, %s le simulateur, %s liste toutes les commandes.",
	["Merge adds the runs your journal is missing and never adds one twice. Replace puts your runs back exactly as they were then."] = "Fusionner ajoute les sorties qui manquent à votre journal et n'en ajoute jamais une deux fois. Remplacer remet vos sorties exactement comme elles étaient alors.",
	["Need (off spec)"] = "Besoin (spé. secondaire)",
	["No backup of your runs yet."] = "Pas encore de sauvegarde de vos sorties.",
	["No roll"] = "Pas de jet",
	["Nothing to read. Paste a runs code first."] = "Rien à lire. Collez d'abord un code de sorties.",
	["On a creature that can drop an item that starts a quest: the item, the quest and the drop chance, until you have the item or did the quest."] = "Sur une créature qui peut laisser tomber un objet qui lance une quête : l'objet, la quête et la chance de butin, jusqu'à ce que vous ayez l'objet ou fait la quête.",
	["Paste a runs code"] = "Coller un code de sorties",
	["Paste a runs code from EldoUI (!EUJR1!). You see what it holds before anything changes."] = "Collez un code de sorties d'EldoUI (!EUJR1!). Vous voyez ce qu'il contient avant que quoi que ce soit change.",
	["Pick a backup of your runs, then Merge or Replace. Your runs are backed up first."] = "Choisissez une sauvegarde de vos sorties, puis Fusionner ou Remplacer. Vos sorties sont sauvegardées d'abord.",
	["Press Ctrl+C to copy the code. Use \"Paste a runs code\" on this PC or another to restore your runs. Nothing is sent anywhere."] = "Appuyez sur Ctrl+C pour copier le code. Utilisez \"Coller un code de sorties\" sur ce PC ou un autre pour restaurer vos sorties. Rien n'est envoyé nulle part.",
	["Restore your runs"] = "Restaurer vos sorties",
	["Restore your runs from %s?"] = "Restaurer vos sorties du %s ?",
	["Runs code"] = "Code de sorties",
	["Show %d earlier runs"] = { one = "Afficher %d sortie précédente", other = "Afficher %d sorties précédentes" },
	["Someone"] = "Quelqu'un",
	["That is not a runs code. A runs code starts with !EUJR1!."] = "Ce n'est pas un code de sorties. Un code de sorties commence par !EUJR1!.",
	["The name leaves every run and your companions; the runs and everyone else stay. Undo brings it back for 7 days."] = "Le nom quitte chaque sortie et vos compagnons ; les sorties et tous les autres restent. Annuler le rétablit pendant 7 jours.",
	["The run leaves your journal; everything else stays. Undo brings it back for 7 days."] = "La sortie quitte votre journal ; tout le reste demeure. Annuler la rétablit pendant 7 jours.",
	["The runs of %s, saved %s."] = "Les sorties de %s, enregistrées %s.",
	["The tooltip line has its own switch on the Tooltip page. The chance follows the Loot Guide's Drop chances setting."] = "La ligne de l'infobulle a son propre interrupteur sur la page Infobulles. La chance suit le réglage Chances de butin du Loot Guide.",
	["There are no runs to back up yet."] = "Il n'y a pas encore de sorties à sauvegarder.",
	["This can be done out of combat only."] = "Impossible de faire ceci tout en combattant.",
	["Transmog"] = "Transmogrification",
	["Updating the list of runs. It fills in by itself in a moment."] = "Mise à jour de la liste des sorties. Elle se remplit d'elle-même dans un instant.",
	["What the pages show; everything is always written down. Essentials: levels, deaths, notes, goals. Storyteller: adds spells, professions and places. Chronicler: everything."] = "Ce que les pages affichent ; tout est toujours noté. L'essentiel : niveaux, morts, notes, objectifs. Conteur : ajoute sorts, métiers et lieux. Chroniqueur : tout.",
	["with %s others"] = { one = "avec %s autre", other = "avec %s autres" },
	["Won with you"] = "Gagné avec vous",
	["Your character's journal in the Journal window: a diary that writes itself, keepsakes, places, quests, goals and notes, your story from 1 to 60 and where to go next."] = "Le journal de votre personnage dans la fenêtre du journal : une chronique qui s'écrit toute seule, souvenirs, lieux, quêtes, objectifs et notes, votre histoire du niveau 1 à 60 et où aller ensuite.",
	["Your runs are back as they were then."] = "Vos sorties sont revenues comme elles étaient alors.",
	["Your runs as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Vos sorties en un seul code, à garder ou à coller sur un autre PC. Rien n'est envoyé nulle part.",
	["Your runs as they are now are backed up first either way."] = "Vos sorties telles qu'elles sont maintenant sont d'abord sauvegardées dans tous les cas.",
} end)
